real function gam1(a)
implicit none
real, intent(in) :: a
real :: bot, d, s1, s2, t, top, w
real :: p(7), q(5), r(9)
!-----------------------------------------------------------------------
!     Computation of 1/gamma(a+1) - 1  For -0.5 .LE. a .LE. 1.5
!-----------------------------------------------------------------------
!------------------------
data p(1)/ .577215664901533e+00/, p(2)/-.409078193005776e+00/, &
   & p(3)/-.230975380857675e+00/, p(4)/ .597275330452234e-01/, &
   & p(5)/ .766968181649490e-02/, p(6)/-.514889771323592e-02/, &
   & p(7)/ .589597428611429e-03/
!------------------------
data q(1)/ .100000000000000e+01/, q(2)/ .427569613095214e+00/, &
   & q(3)/ .158451672430138e+00/, q(4)/ .261132021441447e-01/, &
   & q(5)/ .423244297896961e-02/
!------------------------
data r(1)/-.422784335098468e+00/, r(2)/-.771330383816272e+00/, &
   & r(3)/-.244757765222226e+00/, r(4)/ .118378989872749e+00/, &
   & r(5)/ .930357293360349e-03/, r(6)/-.118290993445146e-01/, &
   & r(7)/ .223047661158249e-02/, r(8)/ .266505979058923e-03/, &
   & r(9)/-.132674909766242e-03/
!------------------------
data s1  / .273076135303957e+00/, s2  / .559398236957378e-01/
!------------------------
t = a
d = a - 0.5
if (d .gt. 0.0) t = d - 0.5
if (t) 30,10,20
!
10 gam1 = 0.0
return
!
20 top = (((((p(7)*t + p(6))*t + p(5))*t + p(4))*t + p(3))*t &
   & + p(2))*t + p(1)
bot = (((q(5)*t + q(4))*t + q(3))*t + q(2))*t + 1.0
w = top/bot
if (d .gt. 0.0) go to 21
gam1 = a*w
return
21 gam1 = (t/a)*((w - 0.5) - 0.5)
return
!
30 top = (((((((r(9)*t + r(8))*t + r(7))*t + r(6))*t + r(5))*t &
   & + r(4))*t + r(3))*t + r(2))*t + r(1)
bot = (s2*t + s1)*t + 1.0
w = top/bot
if (d .gt. 0.0) go to 31
gam1 = a*((w + 0.5) + 0.5)
return
31 gam1 = t*w/a
return
end function gam1

real function gamln (a)
implicit none
real, intent(in) :: a
real :: gamln1
integer :: i, n
real :: c0, c1, c2, c3, c4, c5, d, t, w
!-----------------------------------------------------------------------
!            Evaluation of LN(gamma(a)) for positive A
!-----------------------------------------------------------------------
!     Written by Alfred H. Morris
!          Naval Surface Warfare Center
!          Dahlgren, Virginia
!--------------------------
!     d = 0.5*(ln(2*pi) - 1)
!--------------------------
data d/.418938533204673/
!--------------------------
data c0/.833333333333333e-01/, c1/-.277777777760991e-02/, &
   & c2/.793650666825390e-03/, c3/-.595202931351870e-03/, &
   & c4/.837308034031215e-03/, c5/-.165322962780713e-02/
!-----------------------------------------------------------------------
if (a .gt. 0.8) go to 10
gamln = gamln1(a) - alog(a)
return
10 if (a .gt. 2.25) go to 20
t = (a - 0.5) - 0.5
gamln = gamln1(t)
return
!
20 if (a .ge. 10.0) go to 30
n = a - 1.25
t = a
w = 1.0
do 21 i = 1,n
   t = t - 1.0
21 w = t*w
gamln = gamln1(t - 1.0) + alog(w)
return
!
30 t = (1.0/a)**2
w = (((((c5*t + c4)*t + c3)*t + c2)*t + c1)*t + c0)/a
gamln = (d + w) + (a - 0.5)*(alog(a) - 1.0)
end function gamln

real function gamln1 (a)
implicit none
real, intent(in) :: a
real :: p0, p1, p2, p3, p4, p5, p6, q1, q2, q3, q4, q5, q6, r0, &
   & r1, r2, r3, r4, r5, s1, s2, s3, s4, s5, w, x
!-----------------------------------------------------------------------
!     Evaluation of LN(gamma(1 + a)) for -0.2 .LE. a .LE. 1.25
!-----------------------------------------------------------------------
data p0/ .577215664901533e+00/, p1/ .844203922187225e+00/, &
   & p2/-.168860593646662e+00/, p3/-.780427615533591e+00/, &
   & p4/-.402055799310489e+00/, p5/-.673562214325671e-01/, &
   & p6/-.271935708322958e-02/
data q1/ .288743195473681e+01/, q2/ .312755088914843e+01/, &
   & q3/ .156875193295039e+01/, q4/ .361951990101499e+00/, &
   & q5/ .325038868253937e-01/, q6/ .667465618796164e-03/
!----------------------
data r0/.422784335098467e+00/,  r1/.848044614534529e+00/, &
   & r2/.565221050691933e+00/,  r3/.156513060486551e+00/, &
   & r4/.170502484022650e-01/,  r5/.497958207639485e-03/
data s1/.124313399877507e+01/,  s2/.548042109832463e+00/, &
   & s3/.101552187439830e+00/,  s4/.713309612391000e-02/, &
   & s5/.116165475989616e-03/
!----------------------
if (a .ge. 0.6) go to 10
w = ((((((p6*a + p5)*a + p4)*a + p3)*a + p2)*a + p1)*a + p0)/ &
   & ((((((q6*a + q5)*a + q4)*a + q3)*a + q2)*a + q1)*a + 1.0)
gamln1 = -a*w
return
!
10 x = (a - 0.5) - 0.5
w = (((((r5*x + r4)*x + r3)*x + r2)*x + r1)*x + r0)/ &
   & (((((s5*x + s4)*x + s3)*x + s2)*x + s1)*x + 1.0)
gamln1 = x*w
return
end function gamln1

subroutine dcgama (mo, z, w)
implicit none
integer, intent(in) :: mo
double precision, intent(in) :: z(2)
double precision, intent(inout) :: w(2)
integer :: j, k, max, n, nm1
integer :: ipmpar
double precision :: c0(30), dlpi, hl2p, pi, pi2
double precision :: a, a1, a2, c, cn, cut, d, eps, et, e2t, h1, &
   & h2, q1, q2, s, sn, s1, s2, t, t1, t2, u, u1, u2, v1, v2, w1, w2, &
   & x, y, y2
double precision :: dpmpar, drexp
!-----------------------------------------------------------------------
!
!        Evaluation of the complex gamma and LOGGAMMA functions
!
!                        ---------------
!
!     mo is an integer. z and w are interpreted as double precision
!     COMPLEX NUMBERS. IT IS ASSUMED THAT z(1) AND z(2) ARE THE REAL
!     and imaginary parts of the complex number z, and that w(1) and
!     w(2) are the real and imaginary parts of w.
!
!                 w = gamma(z)       IF mo = 0
!                 w = ln(gamma(z))   otherwise
!
!-----------------------------------------------------------------------
!---------------------------
!     dlpi = log(pi)
!     hl2p = 0.5 * log(2*pi)
!---------------------------
data pi   /3.141592653589793238462643383279502884197d0/
data pi2  /6.283185307179586476925286766559005768394d0/
data dlpi /1.144729885849400174143427351353058711647d0/
data hl2p /.9189385332046727417803297364056176398614d0/
!---------------------------
data c0(1)  / .8333333333333333333333333333333333333333d-01/, &
   & c0(2)  /-.2777777777777777777777777777777777777778d-02/, &
   & c0(3)  / .7936507936507936507936507936507936507937d-03/, &
   & c0(4)  /-.5952380952380952380952380952380952380952d-03/, &
   & c0(5)  / .8417508417508417508417508417508417508418d-03/, &
   & c0(6)  /-.1917526917526917526917526917526917526918d-02/, &
   & c0(7)  / .6410256410256410256410256410256410256410d-02/, &
   & c0(8)  /-.2955065359477124183006535947712418300654d-01/, &
   & c0(9)  / .1796443723688305731649384900158893966944d+00/, &
   & c0(10) /-.1392432216905901116427432216905901116427d+01/
data c0(11) / .1340286404416839199447895100069013112491d+02/, &
   & c0(12) /-.1568482846260020173063651324520889738281d+03/, &
   & c0(13) / .2193103333333333333333333333333333333333d+04/, &
   & c0(14) /-.3610877125372498935717326521924223073648d+05/, &
   & c0(15) / .6914722688513130671083952507756734675533d+06/, &
   & c0(16) /-.1523822153940741619228336495888678051866d+08/, &
   & c0(17) / .3829007513914141414141414141414141414141d+09/, &
   & c0(18) /-.1088226603578439108901514916552510537473d+11/, &
   & c0(19) / .3473202837650022522522522522522522522523d+12/, &
   & c0(20) /-.1236960214226927445425171034927132488108d+14/
data c0(21) / .4887880647930793350758151625180229021085d+15/, &
   & c0(22) /-.2132033396091937389697505898213683855747d+17/, &
   & c0(23) / .1021775296525700077565287628053585500394d+19/, &
   & c0(24) /-.5357547217330020361082770919196920448485d+20/, &
   & c0(25) / .3061578263704883415043151051329622758194d+22/, &
   & c0(26) /-.1899991742639920405029371429306942902947d+24/, &
   & c0(27) / .1276337403382883414923495137769782597654d+26/, &
   & c0(28) /-.9252847176120416307230242348347622779519d+27/, &
   & c0(29) / .7218822595185610297836050187301637922490d+29/, &
   & c0(30) /-.6045183405995856967743148238754547286066d+31/
!---------------------------
!
!     ****** max and eps are machine dependent constants.
!            Max is the largest positive integer that may
!            be used, and eps is the smallest number such
!            THAT  1.D0 + eps .GT. 1.D0.
!
max = ipmpar(3)
eps = dpmpar(1)
!
!---------------------------
x = z(1)
y = z(2)
if (x .ge. 0.d0) go to 50
!-----------------------------------------------------------------------
!            Case when the real part of z is negative
!-----------------------------------------------------------------------
y = dabs(y)
t = -pi*y
et = dexp(t)
e2t = et*et
!
!     SET  a1 = (1 + e2t)/2  AND  a2 = (1 - e2t)/2
!
a1 = 0.5d0*(1.d0 + e2t)
t2 = t + t
if (t2 .lt. -0.15d0) go to 10
a2 = -0.5d0*drexp(t2)
go to 20
10 a2 = 0.5d0*(0.5d0 + (0.5d0 - e2t))
!
!     Compute sin(pi*X) and cos(pi*X)
!
20 u = max
if (dabs(x) .ge. dmin1(u, 1.d0/eps)) go to 200
k = dabs(x)
u = x + k
k = mod(k,2)
if (u .gt. -0.5d0) go to 21
u = 0.5d0 + (0.5d0 + u)
k = k + 1
21 u = pi*u
sn = dsin(u)
cn = dcos(u)
if (k .ne. 1) go to 30
sn = -sn
cn = -cn
!
!     Set  h1 + H2*I  to  pi/sin(pi*z)  or  log(pi/sin(pi*z))
!
30 a1 = sn*a1
a2 = cn*a2
a = a1*a1 + a2*a2
if (a .eq. 0.d0) go to 200
if (mo .ne. 0) go to 40
!
h1 = a1/a
h2 = -a2/a
c = pi*et
h1 = c*h1
h2 = c*h2
go to 41
!
40 h1 = (dlpi + t) - 0.5d0*dlog(a)
h2 = -datan2(a2,a1)
41 if (z(2) .lt. 0.d0) go to 42
x = 1.0 - x
y = -y
go to 50
42 h2 = -h2
x = 1.0 - x
!-----------------------------------------------------------------------
!           Case when the real part of z is nonnegative
!-----------------------------------------------------------------------
50 w1 = 0.d0
w2 = 0.d0
n = 0
t = x
y2 = y*y
a = t*t + y2
cut = 225.d0
if (eps .gt. 1.d-30) cut = 144.d0
if (eps .gt. 1.d-20) cut = 64.d0
if (a .ge. cut) go to 80
if (a .eq. 0.d0) go to 200
51 n = n + 1
t = t + 1.d0
a = t*t + y2
if (a .lt. cut) go to 51
!
!     Let S1 + S2*I be the product of the terms (z+j)/(z+n)
!
u1 = (x*t + y2)/a
u2 = y/a
s1 = u1
s2 = n*u2
if (n .lt. 2) go to 70
u = t/a
nm1 = n - 1
do j = 1,nm1
   v1 = u1 + j*u
   v2 = (n - j)*u2
   c = s1*v1 - s2*v2
   d = s1*v2 + s2*v1
   s1 = c
   s2 = d
end do
!
!     Set  W1 + W2*I = log(S1 + S2*I)  when mo is nonzero
!
70 s = s1*s1 + s2*s2
if (mo .eq. 0) go to 80
w1 = 0.5d0 * dlog(s)
w2 = datan2(s2,s1)
!
!     SET  V1 + V2*I = (z - 0.5) * log(z + n) - z
!
80 t1 = 0.5d0 * dlog(a) - 1.d0
t2 = datan2(y,t)
u = x - 0.5d0
v1 = (u*t1 - 0.5d0) - y*t2
v2 = u*t2 + y*t1
!
!     Let a1 + a2*I be the asymptotic sum
!
u1 = t/a
u2 = -y/a
q1 = u1*u1 - u2*u2
q2 = 2.d0*u1*u2
a1 = 0.d0
a2 = 0.d0
do j = 1,30
   t1 = a1
   t2 = a2
   a1 = a1 + c0(j)*u1
   a2 = a2 + c0(j)*u2
   if (a1 .ne. t1) go to 90
   if (a2 .eq. t2) go to 100
90 t1 = u1*q1 - u2*q2
   t2 = u1*q2 + u2*q1
   u1 = t1
   u2 = t2
end do
!-----------------------------------------------------------------------
!                 Gathering together the results
!-----------------------------------------------------------------------
100 w1 = (((a1 + hl2p) - w1) + v1) - n
w2 = (a2 - w2) + v2
if (z(1) .lt. 0.d0) go to 120
if (mo .ne. 0) go to 110
!
!     Case when the real part of z is nonnegative and mo = 0
!
a = dexp(w1)
w1 = a * dcos(w2)
w2 = a * dsin(w2)
if (n .eq. 0) go to 140
c = (s1*w1 + s2*w2)/s
d = (s1*w2 - s2*w1)/s
w1 = c
w2 = d
go to 140
!
!     Case when the real part of z is nonnegative and mo is nonzero.
!     The angle W2 is reduced to the interval -pi .LT. W2 .LE. pi.
!
110 if (w2 .gt. pi) go to 111
k = 0.5d0 - w2/pi2
w2 = w2 + pi2*k
go to 140
111 k = w2/pi2 - 0.5d0
u = k + 1
w2 = w2 - pi2*u
if (w2 .le. -pi) w2 = pi
go to 140
!
!     Case when the real part of z is negative and mo is nonzero
!
120 if (mo .eq. 0) go to 130
w1 = h1 - w1
w2 = h2 - w2
go to 110
!
!     Case when the real part of z is negative and mo = 0
!
130 a = dexp(-w1)
t1 = a * dcos(-w2)
t2 = a * dsin(-w2)
w1 = h1*t1 - h2*t2
w2 = h1*t2 + h2*t1
if (n .eq. 0) go to 140
c = w1*s1 - w2*s2
d = w1*s2 + w2*s1
w1 = c
w2 = d
!
!     Termination
!
140 w(1) = w1
w(2) = w2
return
!-----------------------------------------------------------------------
!             The requested value cannot be computed
!-----------------------------------------------------------------------
200 w(1) = 0.d0
w(2) = 0.d0
return
end subroutine dcgama

double precision function dgamma(a)
implicit none
double precision, intent(in) :: a
integer :: j, n
double precision :: d, pi, s, t, x, w
double precision :: dpmpar, dsin1, dgam1, dpdel, dxparg
!-----------------------------------------------------------------------
!
!                Evaluation of the gamma function for
!                     double precision arguments
!
!                           -----------
!
!     dgamma(a) is assigned the value 0 when the gamma function CANNOT
!     be computed.
!
!-----------------------------------------------------------------------
!     Written by Alfred H. Morris, Jr.
!          naval surface weapons center
!          Dahlgren, Virginia
!-----------------------------------------------------------------------
!-----------------------------------------------------------------------
!     d = 0.5*(ln(2*pi) - 1)
!-----------------------------------------------------------------------
data pi /3.14159265358979323846264338327950d0/
data d  /0.41893853320467274178032973640562d0/
!-----------------------------------------------------------------------
dgamma = 0.d0
x = a
if (dabs(a) .gt. 20.d0) go to 60
!-----------------------------------------------------------------------
!             Evaluation of dgamma(a) for dabs(a) .LE. 20
!-----------------------------------------------------------------------
t = 1.d0
n = x
n = n - 1
!
!     Let t be the product of a-j when a .GE. 2
!
if (n) 20,12,10
10 do 11 j = 1,n
   x = x - 1.d0
11 t = x*t
12 x = x - 1.d0
go to 40
!
!     Let t be the product of a+j when a .LT. 1
!
20 t = a
if (a .gt. 0.d0) go to 30
n = - n - 1
if (n .eq. 0) go to 22
do 21 j = 1,n
   x = x + 1.d0
21 t = x*t
22 x = (x + 0.5d0) + 0.5d0
t = x*t
if (t .eq. 0.d0) return
!
30 continue
!
!     The following code checks if 1/t can overflow. This
!     code may be omitted if desired.
!
if (dabs(t) .ge. 1.d-33) go to 40
if (dabs(t)*dpmpar(3) .le. 1.000000001d0) return
dgamma = 1.d0/t
return
!
!     Compute dgamma(1 + x) for 0 .LE. x .LT. 1
!
40 dgamma = 1.d0/(1.d0 + dgam1(x))
!
!     Termination
!
if (a .lt. 1.d0) go to 50
dgamma = dgamma * t
return
50 dgamma = dgamma / t
return
!-----------------------------------------------------------------------
!           Evaluation of dgamma(a) for dabs(a) .GT. 20
!-----------------------------------------------------------------------
60 if (dabs(a) .ge. 1.d3) return
if (a .gt. 0.d0) go to 70
s = dsin1(a)/pi
if (s .eq. 0.d0) return
x = -a
!
!     Compute the modified asymptotic sum
!
70 w = dpdel(x)
!
!     Final assembly
!
w = (d + w) + (x - 0.5d0)*(dlog(x) - 1.d0)
if (w .gt. dxparg(0)) return
dgamma = dexp(w)
if (a .lt. 0.d0) dgamma = (1.d0/(dgamma*s))/x
return
end function dgamma

double precision function dpdel(x)
implicit none
double precision, intent(in) :: x
integer :: i, k
double precision :: a(15), t, w
!-----------------------------------------------------------------------
!
!     Computation of the function DEL(x) for  x .GE. 10  where
!     LN(gamma(x)) = (x - 0.5)*LN(x) - x + 0.5*LN(2*PI) + DEL(x)
!
!                         --------
!
!     The series for dpdel on the interval 0.0 to 1.0 derived by
!     A.H. Morris from the Chebyshev series in the SLATEC library
!     obtained by Wayne Fullerton (Los Alamos).
!
!-----------------------------------------------------------------------
!-----------------------------------------------------------------------
data a(1)  / .833333333333333333333333333333d-01/, &
   & a(2)  /-.277777777777777777777777752282d-04/, &
   & a(3)  / .793650793650793650791732130419d-07/, &
   & a(4)  /-.595238095238095232389839236182d-09/, &
   & a(5)  / .841750841750832853294451671990d-11/, &
   & a(6)  /-.191752691751854612334149171243d-12/, &
   & a(7)  / .641025640510325475730918472625d-14/, &
   & a(8)  /-.295506514125338232839867823991d-15/, &
   & a(9)  / .179643716359402238723287696452d-16/, &
   & a(10) /-.139228964661627791231203060395d-17/
data a(11) / .133802855014020915603275339093d-18/, &
   & a(12) /-.154246009867966094273710216533d-19/, &
   & a(13) / .197701992980957427278370133333d-20/, &
   & a(14) /-.234065664793997056856992426667d-21/, &
   & a(15) / .171348014966398575409015466667d-22/
!-----------------------------------------------------------------------
t = (10.d0/x)**2
w = a(15)
do 10 i = 1,14
   k = 15 - i
   w = t*w + a(k)
10 continue
dpdel = w/x
return
end function dpdel

double precision function dgam1 (x)
implicit none
!-----------------------------------------------------------------------
!     Evaluation of 1/gamma(1 + x) - 1  For -0.5 .LE. x .LE. 1.5
!-----------------------------------------------------------------------
!
!     The following are the first 49 coefficients of the Maclaurin
!     expansion for 1/gamma(1 + x) - 1. The coefficients are
!     correct to 40 digits. The coefficients were obtained by
!     Alfred H. Morris Jr. (Naval Surface Warfare Center) and are
!     given here for reference. Only the first 14 coefficients are
!     used in this code.
!
!                           -----------
!
!     data a(1)  / .5772156649015328606065120900824024310422d+00/,
!    *     A(2)  /-.6558780715202538810770195151453904812798d+00/,
!    *     A(3)  /-.4200263503409523552900393487542981871139d-01/,
!    *     A(4)  / .1665386113822914895017007951021052357178d+00/,
!    *     A(5)  /-.4219773455554433674820830128918739130165d-01/,
!    *     A(6)  /-.9621971527876973562114921672348198975363d-02/,
!    *     A(7)  / .7218943246663099542395010340446572709905d-02/,
!    *     A(8)  /-.1165167591859065112113971084018388666809d-02/,
!    *     A(9)  /-.2152416741149509728157299630536478064782d-03/,
!    *     A(10) / .1280502823881161861531986263281643233949d-03/
!     data a(11) /-.2013485478078823865568939142102181838229d-04/,
!    *     A(12) /-.1250493482142670657345359473833092242323d-05/,
!    *     A(13) / .1133027231981695882374129620330744943324d-05/,
!    *     A(14) /-.2056338416977607103450154130020572836513d-06/,
!    *     A(15) / .6116095104481415817862498682855342867276d-08/,
!    *     A(16) / .5002007644469222930055665048059991303045d-08/,
!    *     A(17) /-.1181274570487020144588126565436505577739d-08/,
!    *     A(18) / .1043426711691100510491540332312250191401d-09/,
!    *     A(19) / .7782263439905071254049937311360777226068d-11/,
!    *     A(20) /-.3696805618642205708187815878085766236571d-11/
!     data a(21) / .5100370287454475979015481322863231802727d-12/,
!    *     A(22) /-.2058326053566506783222429544855237419746d-13/,
!    *     A(23) /-.5348122539423017982370017318727939948990d-14/,
!    *     A(24) / .1226778628238260790158893846622422428165d-14/,
!    *     A(25) /-.1181259301697458769513764586842297831212d-15/,
!    *     A(26) / .1186692254751600332579777242928674071088d-17/,
!    *     A(27) / .1412380655318031781555803947566709037086d-17/,
!    *     A(28) /-.2298745684435370206592478580633699260285d-18/,
!    *     A(29) / .1714406321927337433383963370267257066813d-19/,
!    *     A(30) / .1337351730493693114864781395122268022875d-21/
!     data a(31) /-.2054233551766672789325025351355733796682d-21/,
!    *     A(32) / .2736030048607999844831509904330982014865d-22/,
!    *     A(33) /-.1732356445910516639057428451564779799070d-23/,
!    *     A(34) /-.2360619024499287287343450735427531007926d-25/,
!    *     A(35) / .1864982941717294430718413161878666898946d-25/,
!    *     A(36) /-.2218095624207197204399716913626860379732d-26/,
!    *     A(37) / .1297781974947993668824414486330594165619d-27/,
!    *     A(38) / .1180697474966528406222745415509971518560d-29/,
!    *     A(39) /-.1124584349277088090293654674261439512119d-29/,
!    *     A(40) / .1277085175140866203990206677751124647749d-30/
!     data a(41) /-.7391451169615140823461289330108552823711d-32/,
!    *     A(42) / .1134750257554215760954165259469306393009d-34/,
!    *     A(43) / .4639134641058722029944804907952228463058d-34/,
!    *     A(44) /-.5347336818439198875077418196709893320905d-35/,
!    *     A(45) / .3207995923613352622861237279082794391090d-36/,
!    *     A(46) /-.4445829736550756882101590352124643637401d-38/,
!    *     A(47) /-.1311174518881988712901058494389922190237d-38/,
!    *     A(48) / .1647033352543813886818259327906394145400d-39/,
!    *     A(49) /-.1056233178503581218600561071538285049997d-40/
!
!                           -----------
!
!     c = A(1) - 1 Is also frequently needed. c has the value ...
!
!     data c /-.4227843350984671393934879099175975689578d+00/
!
!-----------------------------------------------------------------------
double precision, intent(in) :: x
double precision :: d, t, w, z
double precision :: a0, a1, b1, b2, b3, b4, b5, b6, b7, b8
double precision :: p0, p1, p2, p3, p4, p5, p6, q1, q2, q3, q4
double precision :: c, c0, c1, c2, c3, c4, c5, c6, c7, c8, c9, &
   & c10, c11, c12, c13
!----------------------------
data a0 / .611609510448141581788d-08/, &
   & a1 / .624730830116465516210d-08/
data b1 / .203610414066806987300d+00/, &
   & b2 / .266205348428949217746d-01/, &
   & b3 / .493944979382446875238d-03/, &
   & b4 /-.851419432440314906588d-05/, &
   & b5 /-.643045481779353022248d-05/, &
   & b6 / .992641840672773722196d-06/, &
   & b7 /-.607761895722825260739d-07/, &
   & b8 / .195755836614639731882d-09/
!----------------------------
data p0 /.6116095104481415817861d-08/, &
   & p1 /.6871674113067198736152d-08/, &
   & p2 /.6820161668496170657918d-09/, &
   & p3 /.4686843322948848031080d-10/, &
   & p4 /.1572833027710446286995d-11/, &
   & p5/-.1249441572276366213222d-12/, &
   & p6 /.4343529937408594255178d-14/
data q1 /.3056961078365221025009d+00/, &
   & q2 /.5464213086042296536016d-01/, &
   & q3 /.4956830093825887312020d-02/, &
   & q4 /.2692369466186361192876d-03/
!----------------------------
!     c = c0 - 1
!----------------------------
data c /-.422784335098467139393487909917598d+00/
!----------------------------
data c0  / .577215664901532860606512090082402d+00/, &
   & c1  /-.655878071520253881077019515145390d+00/, &
   & c2  /-.420026350340952355290039348754298d-01/, &
   & c3  / .166538611382291489501700795102105d+00/, &
   & c4  /-.421977345555443367482083012891874d-01/, &
   & c5  /-.962197152787697356211492167234820d-02/, &
   & c6  / .721894324666309954239501034044657d-02/, &
   & c7  /-.116516759185906511211397108401839d-02/, &
   & c8  /-.215241674114950972815729963053648d-03/, &
   & c9  / .128050282388116186153198626328164d-03/
data c10 /-.201348547807882386556893914210218d-04/, &
   & c11 /-.125049348214267065734535947383309d-05/, &
   & c12 / .113302723198169588237412962033074d-05/, &
   & c13 /-.205633841697760710345015413002057d-06/
!----------------------------
t = x
d = x - 0.5d0
if (d .gt. 0.d0) t = d - 0.5d0
if (t) 40,10,20
!
10 dgam1 = 0.d0
return
!------------
!
!                Case when 0 .LT. t .LE. 0.5
!
!              w is a minimax approximation for
!              the series A(15) + A(16)*t + ...
!
!------------
20 w = ((((((p6*t + p5)*t + p4)*t + p3)*t + p2)*t + p1)*t + p0)/ &
   & ((((q4*t + q3)*t + q2)*t + q1)*t + 1.d0)
z = (((((((((((((w*t + c13)*t + c12)*t + c11)*t + c10)*t + &
   & c9)*t + c8)*t + c7)*t + c6)*t + c5)*t + c4)*t + &
   & c3)*t + c2)*t + c1)*t + c0
!
if (d .gt. 0.d0) go to 30
dgam1 = x*z
return
30 dgam1 = (t/x)*((z - 0.5d0) - 0.5d0)
return
!------------
!
!                Case when -0.5 .LE. t .LT. 0
!
!              w is a minimax approximation for
!              the series A(15) + A(16)*t + ...
!
!------------
40 w = (a1*t + a0)/((((((((b8*t + b7)*t + b6)*t + b5)*t + &
   & b4)*t + b3)*t + b2)*t + b1)*t + 1.d0)
z = (((((((((((((w*t + c13)*t + c12)*t + c11)*t + c10)*t + &
   & c9)*t + c8)*t + c7)*t + c6)*t + c5)*t + c4)*t + &
   & c3)*t + c2)*t + c1)*t + c
!
if (d .gt. 0.d0) go to 50
dgam1 = x*((z + 0.5d0) + 0.5d0)
return
50 dgam1 = t*z/x
return
end function dgam1

double precision function dgamln (a)
implicit none
double precision, intent(in) :: a
integer :: i, n
double precision :: d, x, w
double precision :: dgmln1, dpdel
!-----------------------------------------------------------------------
!
!           Evaluation of LN(gamma(a)) for positive A
!
!-----------------------------------------------------------------------
!     Written by Alfred H. Morris
!          naval surface weapons center
!          Dahlgren, Virginia
!-----------------------------------------------------------------------
!     d = 0.5*(ln(2*pi) - 1)
!-----------------------------------------------------------------------
!--------------------------
data d /0.41893853320467274178032973640562d0/
!--------------------------
if (a .ge. 0.5d0) go to 10
dgamln = dgmln1(a) - dlog(a)
return
10 if (a .gt. 2.5d0) go to 20
x = a - 1.d0
if (a .lt. 1.d0) x = (a - 0.5d0) - 0.5d0
dgamln = dgmln1(x)
return
!
20 if (a .ge. 10.d0) go to 30
n = a - 1.5d0
x = a
w = 1.d0
do 21 i = 1,n
   x = x - 1.d0
21 w = x*w
dgamln = dgmln1(x - 1.d0) + dlog(w)
return
!
30 w = dpdel(a)
dgamln = (d + w) + (a - 0.5d0)*(dlog(a) - 1.d0)
end function dgamln

double precision function dgmln1 (x)
implicit none
!-----------------------------------------------------------------------
!     Evaluation of LN(gamma(1 + x)) for -0.5 .LE. x .LE. 1.5
!-----------------------------------------------------------------------
double precision, intent(in) :: x
double precision :: w
double precision :: dgam1, dlnrel
!-----------------------
w = dgam1(x)
dgmln1 = - dlnrel(w)
return
end function dgmln1

subroutine cpsi (z, w)
implicit none
complex, intent(in) :: z
complex, intent(inout) :: w
integer :: j, k, l, m, max
real :: a, a1, a2, c1, c2, cn, eps, et, h1, h2, pi, pi2, s, s1, &
   & s2, sn, t, u, w1, w2, x, y, y2
real :: rexp
integer :: ipmpar
real :: spmpar
complex :: eta, eta2, sum
real :: c0(12)
double precision :: ds1, ds2
!-----------------------------------------------------------------------
!           Evaluation of the complex digamma function
!-----------------------------------------------------------------------
!----------------------------
!     pi2 = 2*pi
!----------------------------
data pi/3.14159265358979324/
data pi2/6.28318530717958648/
!----------------------------
data c0(1) /.833333333333333e-01/, c0(2) /-.833333333333333e-02/, &
   & c0(3) /.396825396825397e-02/, c0(4) /-.416666666666667e-02/, &
   & c0(5) /.757575757575758e-02/, c0(6) /-.210927960927961e-01/, &
   & c0(7) /.833333333333333e-01/, c0(8) /-.443259803921569e+00/, &
   & c0(9) /.305395433027012e+01/, c0(10)/-.264562121212121e+02/, &
   & c0(11)/.281460144927536e+03/, c0(12)/-.360751054639805e+04/
!----------------------------
!
!     ****** max and eps are machine dependent constants.
!            Max is the largest positive integer that may
!            be used, and eps is the smallest real number
!            such that 1.0 + eps .GT. 1.0.
!
max = ipmpar(3)
eps = spmpar(1)
!
!----------------------------
x = real(z)
y = aimag(z)
if (x .ge. 0.0) go to 40
!-----------------------------------------------------------------------
!            Case when the real part of z is negative
!-----------------------------------------------------------------------
y = abs(y)
t = -pi2*y
et = exp(t)
!
!     SET  a1 = (1 + et)/2  AND  a2 = (1 - et)/2
!
a1 = 0.5*(1.0 + et)
if (t .lt. -0.15) go to 10
a2 = -0.5*rexp(t)
go to 20
10 a2 = 0.5*(0.5 + (0.5 - et))
!
!     Compute sin(pi*X) and cos(pi*X), or -sin(pi*X) and -cos(pi*X)
!
20 if (abs(x) .ge. amin1(float(max), 1.0/eps)) go to 100
k = abs(x)
u = x + k
if (u .le. -0.5) u = 0.5 + (0.5 + u)
u = pi*u
sn = sin(u)
cn = cos(u)
!
!     SET h1 + h2*I = pi*COT(pi*z)
!
s1 = a1*sn
s2 = a2*cn
c1 = a1*cn
c2 = -a2*sn
s = s1*s1 + s2*s2
h1 = pi*(s1*c1 + s2*c2)/s
h2 = pi*(s1*c2 - s2*c1)/s
!
if (aimag(z) .lt. 0.0) go to 30
x = 1.0 - x
y = -y
go to 40
30 h2 = -h2
x = 1.0 - x
!-----------------------------------------------------------------------
!           Case when the real part of z is nonnegative
!-----------------------------------------------------------------------
40 t = x
y2 = y*y
a = x*x + y2
if (a .eq. 0.0) go to 100
!
!     Let s1 + S2*I be the sum of the terms 1/(z+j) for j = 0,1,...,N-1
!
ds1 = 0.d0
ds2 = 0.d0
50 if (a .ge. 36.0) go to 51
ds1 = ds1 + dble(t/a)
ds2 = ds2 - dble(y/a)
t = t + 1.0
a = t*t + y2
go to 50
51 s1 = ds1
s2 = ds2
!
!     SET W1 + W2*I = log(z+N)
!
w1 = 0.5*alog(a)
w2 = atan2(y,t)
!
!     Let a1 + a2*I be the asymptotic sum
!
eta = cmplx(t/a,-y/a)
eta2 = eta*eta
m = 12
l = m
sum = cmplx(c0(m),0.0)
do j = 2,m
   l = l - 1
   sum = cmplx(c0(l),0.0) + sum*eta2
end do
sum = cmplx(0.5,0.0)*eta + eta2*sum
a1 = real(sum)
a2 = aimag(sum)
!-----------------------------------------------------------------------
!                 Gathering together the results
!-----------------------------------------------------------------------
w1 = (w1 - s1) - a1
w2 = (w2 - a2) - s2
w = cmplx(w1,w2)
if (real(z) .ge. 0.0) return
w = cmplx(w1 - h1, w2 - h2)
return
!-----------------------------------------------------------------------
!             The requested value cannot be computed
!-----------------------------------------------------------------------
100 w = (0.0, 0.0)
return
end subroutine cpsi

real function psi(xx)
implicit none
real, intent(in) :: xx
integer :: ipmpar
real :: spmpar
integer :: i, m, n, nq
real :: aug, den, piov4, sgn, upper, w, x, xmax1, xmx0, xsmall, z
real :: p1(7), p2(4), q1(6), q2(4)
double precision :: dx0
!---------------------------------------------------------------------
!
!                 Evaluation of the digamma function
!
!                           -----------
!
!     psi(xx) is assigned the value 0 when the digamma function CANNOT
!     be computed.
!
!     The main computation involves evaluation of rational Chebyshev
!     approximations published in math. Comp. 27, 123-127(1973) By
!     Cody, Strecok and Thacher.
!
!---------------------------------------------------------------------
!     Psi was written at Argonne National Laboratory for the funpack
!     package of special function subroutines. Psi was modified by
!     A.H. Morris (NSWC).
!---------------------------------------------------------------------
!---------------------------------------------------------------------
!
!     piov4 = pi/4
!     dx0 = Zero of psi to extended precision
!
!---------------------------------------------------------------------
data piov4/.785398163397448e0/
data dx0/1.461632144968362341262659542325721325d0/
!---------------------------------------------------------------------
!
!     Coefficients for rational approximation of
!     psi(x) / (x - X0),  0.5 .LE. x .LE. 3.0
!
!---------------------------------------------------------------------
data p1(1)/.895385022981970e-02/,  p1(2)/.477762828042627e+01/, &
   & p1(3)/.142441585084029e+03/,  p1(4)/.118645200713425e+04/, &
   & p1(5)/.363351846806499e+04/,  p1(6)/.413810161269013e+04/, &
   & p1(7)/.130560269827897e+04/
data q1(1)/.448452573429826e+02/,  q1(2)/.520752771467162e+03/, &
   & q1(3)/.221000799247830e+04/,  q1(4)/.364127349079381e+04/, &
   & q1(5)/.190831076596300e+04/,  q1(6)/.691091682714533e-05/
!---------------------------------------------------------------------
!
!     Coefficients for rational approximation of
!     psi(x) - LN(x) + 1 / (2*x),  x .GT. 3.0
!
!---------------------------------------------------------------------
data p2(1)/-.212940445131011e+01/, p2(2)/-.701677227766759e+01/, &
   & p2(3)/-.448616543918019e+01/, p2(4)/-.648157123766197e+00/
data q2(1)/ .322703493791143e+02/, q2(2)/ .892920700481861e+02/, &
   & q2(3)/ .546117738103215e+02/, q2(4)/ .777788548522962e+01/
!---------------------------------------------------------------------
!
!     Machine dependent constants ...
!
!        xmax1  = The smallest positive floating point constant
!                 with entirely integer representation.  Also used
!                 as negative of lower bound on acceptable negative
!                 arguments and as the positive argument beyond which
!                 psi may be represented as ALOG(x).
!
!        xsmall = Absolute argument below which pi*cotan(PI*x)
!                 may be represented by 1/x.
!
!---------------------------------------------------------------------
xmax1 = ipmpar(3)
xmax1 = amin1(xmax1, 1.0/spmpar(1))
xsmall = 1.e-9
!---------------------------------------------------------------------
x = xx
aug = 0.0e0
if (x .ge. 0.5e0) go to 200
!---------------------------------------------------------------------
!     x .LT. 0.5,  use reflection formula
!     psi(1-x) = psi(x) + pi * cotan(pi*x)
!---------------------------------------------------------------------
if (abs(x) .gt. xsmall) go to 100
if (x .eq. 0.0e0) go to 400
!---------------------------------------------------------------------
!     0 .LT. abs(x) .LE. xsmall.  USE 1/x AS A SUBSTITUTE
!     for  pi*cotan(PI*x)
!---------------------------------------------------------------------
aug = -1.0e0 / x
go to 150
!---------------------------------------------------------------------
!     Reduction of argument for cotan
!---------------------------------------------------------------------
100 w = - x
sgn = piov4
if (w .gt. 0.0e0) go to 120
w = - w
sgn = -sgn
!---------------------------------------------------------------------
!     Make an error exit if x .LE. -xmax1
!---------------------------------------------------------------------
120 if (w .ge. xmax1) go to 400
nq = int(w)
w = w - float(nq)
nq = int(w*4.0e0)
w = 4.0e0 * (w - float(nq) * .25e0)
!---------------------------------------------------------------------
!     w is now related to the fractional part of  4.0 * x.
!     Adjust argument to correspond to values in first
!     quadrant and determine sign
!---------------------------------------------------------------------
n = nq / 2
if ((n + n) .ne. nq) w = 1.0e0 - w
z = piov4 * w
m = n / 2
if ((m + m) .ne. n) sgn = - sgn
!---------------------------------------------------------------------
!     Determine final value for  -Pi*cotan(PI*x)
!---------------------------------------------------------------------
n = (nq + 1) / 2
m = n / 2
m = m + m
if (m .ne. n) go to 140
!---------------------------------------------------------------------
!     Check for singularity
!---------------------------------------------------------------------
if (z .eq. 0.0e0) go to 400
!---------------------------------------------------------------------
!     Use cos/sin as a substitute for cotan, and
!     sin/cos as a substitute for tan
!---------------------------------------------------------------------
aug = sgn * ((cos(z) / sin(z)) * 4.0e0)
go to 150
140 aug = sgn * ((sin(z) / cos(z)) * 4.0e0)
150 x = 1.0e0 - x
200 if (x .gt. 3.0e0) go to 300
!---------------------------------------------------------------------
!     0.5 .LE. x .LE. 3.0
!---------------------------------------------------------------------
den = x
upper = p1(1) * x
!
do i = 1, 5
   den = (den + q1(i)) * x
   upper = (upper + p1(i + 1)) * x
end do
!
den = (upper + p1(7)) / (den + q1(6))
xmx0 = dble(x) - dx0
psi = den * xmx0 + aug
return
!---------------------------------------------------------------------
!     IF x .GE. xmax1, PSI = LN(x)
!---------------------------------------------------------------------
300 if (x .ge. xmax1) go to 350
!---------------------------------------------------------------------
!     3.0 .LT. x .LT. xmax1
!---------------------------------------------------------------------
w = 1.0e0 / (x * x)
den = w
upper = p2(1) * w
!
do i = 1, 3
   den = (den + q2(i)) * w
   upper = (upper + p2(i + 1)) * w
end do
!
aug = upper / (den + q2(4)) - 0.5e0 / x + aug
350 psi = aug + alog(x)
return
!---------------------------------------------------------------------
!     Error return
!---------------------------------------------------------------------
400 psi = 0.0e0
return
end function psi

subroutine dcpsi (z, w)
implicit none
double precision, intent(in) :: z(2)
double precision, intent(inout) :: w(2)
integer :: j, k, m, max
integer :: ipmpar
double precision :: c0(30), pi, pi2
double precision :: a, a1, a2, cn, cut, c1, c2, eps, et, h1, h2, &
   & q1, q2, s, sn, s1, s2, t, t1, t2, u, u1, u2, v1, v2, w1, w2, x, y, &
   & y2
double precision :: drexp, dpmpar
!-----------------------------------------------------------------------
!           Evaluation of the complex digamma function
!-----------------------------------------------------------------------
!----------------------------
!     pi2 = 2*pi
!----------------------------
data pi   /3.141592653589793238462643383279502884197d0/
data pi2  /6.283185307179586476925286766559005768394d0/
!----------------------------
data c0(1)  / .8333333333333333333333333333333333333333d-01/, &
   & c0(2)  /-.8333333333333333333333333333333333333333d-02/, &
   & c0(3)  / .3968253968253968253968253968253968253968d-02/, &
   & c0(4)  /-.4166666666666666666666666666666666666667d-02/, &
   & c0(5)  / .7575757575757575757575757575757575757576d-02/, &
   & c0(6)  /-.2109279609279609279609279609279609279609d-01/, &
   & c0(7)  / .8333333333333333333333333333333333333333d-01/, &
   & c0(8)  /-.4432598039215686274509803921568627450980d+00/, &
   & c0(9)  / .3053954330270119743803954330270119743804d+01/, &
   & c0(10) /-.2645621212121212121212121212121212121212d+02/
data c0(11) / .2814601449275362318840579710144927536232d+03/, &
   & c0(12) /-.3607510546398046398046398046398046398046d+04/, &
   & c0(13) / .5482758333333333333333333333333333333333d+05/, &
   & c0(14) /-.9749368238505747126436781609195402298851d+06/, &
   & c0(15) / .2005269579668807894614346227249453055905d+08/, &
   & c0(16) /-.4723848677216299019607843137254901960784d+09/, &
   & c0(17) / .1263572479591666666666666666666666666667d+11/, &
   & c0(18) /-.3808793112524536881155302207933786881155d+12/, &
   & c0(19) / .1285085049930508333333333333333333333333d+14/, &
   & c0(20) /-.4824144835485017037158167036215816703622d+15/
data c0(21) / .2004031065651625273810842166323893898645d+17/, &
   & c0(22) /-.9167743603195330775699275362318840579710d+18/, &
   & c0(23) / .4597988834365650349043794326241134751773d+20/, &
   & c0(24) /-.2518047192145109569708902332022552610788d+22/, &
   & c0(25) / .1500173349215392873371144015151515151515d+24/, &
   & c0(26) /-.9689957887463594065649794289465408805031d+25/, &
   & c0(27) / .6764588237929282099094524230179847767567d+27/, &
   & c0(28) /-.5089065946866228968976633291591192528736d+29/, &
   & c0(29) / .4114728879255797869766548606761933615819d+31/, &
   & c0(30) /-.3566658209537555610968457460865182898779d+33/
!----------------------------
!
!     ****** max and eps are machine dependent constants.
!            Max is the largest positive integer that may
!            be used, and eps is the smallest real number
!            such that 1.D0 + eps .GT. 1.D0.
!
max = ipmpar(3)
eps = dpmpar(1)
!
!----------------------------
x = z(1)
y = z(2)
if (x .ge. 0.d0) go to 40
!-----------------------------------------------------------------------
!            Case when the real part of z is negative
!-----------------------------------------------------------------------
y = dabs(y)
t = -pi2*y
et = dexp(t)
!
!     SET  a1 = (1 + et)/2  AND  a2 = (1 - et)/2
!
a1 = 0.5d0*(1.d0 + et)
if (t .lt. -0.15d0) go to 10
a2 = -0.5d0*drexp(t)
go to 20
10 a2 = 0.5d0*(0.5d0 + (0.5d0 - et))
!
!     Compute sin(pi*X) and cos(pi*X), or -sin(pi*X) and -cos(pi*X)
!
20 u = max
if (dabs(x) .ge. dmin1(u, 1.d0/eps)) go to 100
k = dabs(x)
u = x + k
if (u .le. -0.5d0) u = 0.5d0 + (0.5d0 + u)
u = pi*u
sn = dsin(u)
cn = dcos(u)
!
!     SET h1 + h2*I = pi*COT(pi*z)
!
s1 = a1*sn
s2 = a2*cn
c1 = a1*cn
c2 = -a2*sn
s = s1*s1 + s2*s2
h1 = pi*(s1*c1 + s2*c2)/s
h2 = pi*(s1*c2 - s2*c1)/s
!
if (z(2) .lt. 0.d0) go to 30
x = 1.d0 - x
y = -y
go to 40
30 h2 = -h2
x = 1.d0 - x
!-----------------------------------------------------------------------
!           Case when the real part of z is nonnegative
!-----------------------------------------------------------------------
40 t = x
y2 = y*y
a = x*x + y2
if (a .eq. 0.d0) go to 100
cut = 225.d0
if (eps .gt. 1.d-30) cut = 144.d0
!
!     Let S1 + S2*I be the sum of the terms 1/(z+j) for j = 0,1,...,N-1
!
s1 = 0.d0
s2 = 0.d0
50 if (a .ge. cut) go to 51
s1 = s1 + t/a
s2 = s2 - y/a
t = t + 1.d0
a = t*t + y2
go to 50
51 continue
!
!     SET W1 + W2*I = log(z+N)
!
w1 = 0.5d0*dlog(a)
w2 = datan2(y,t)
!
!     Let a1 + a2*I be the asymptotic sum
!
u1 = t/a
u2 = -y/a
q1 = u1*u1 - u2*u2
q2 = 2.d0*u1*u2
v1 = q1
v2 = q2
a1 = 0.d0
a2 = 0.d0
m = 30
if (eps .gt. 1.d-30) m = 25
do 61 j = 1,m
   t1 = a1
   t2 = a2
   a1 = a1 + c0(j)*v1
   a2 = a2 + c0(j)*v2
   if (a1 .ne. t1) go to 60
   if (a2 .eq. t2) go to 70
60 t1 = v1*q1 - v2*q2
   t2 = v1*q2 + v2*q1
   v1 = t1
61 v2 = t2
!-----------------------------------------------------------------------
!                 Gathering together the results
!-----------------------------------------------------------------------
70 a1 = a1 + 0.5d0*u1
a2 = a2 + 0.5d0*u2
w(1) = (w1 - a1) - s1
w(2) = (w2 - a2) - s2
if (z(1) .ge. 0.d0) return
w(1) = w(1) - h1
w(2) = w(2) - h2
return
!-----------------------------------------------------------------------
!             The requested value cannot be computed
!-----------------------------------------------------------------------
100 w(1) = 0.d0
w(2) = 0.d0
return
end subroutine dcpsi

double precision function dpsi(a)
implicit none
double precision, intent(in) :: a
integer :: ipmpar
integer :: j, k, l, max, n
double precision :: c(42), eps, p(15), pi, s, t, x, x0, xmax, w
double precision :: dcsevl, dpsi0, dpmpar
!-----------------------------------------------------------------------
!
!               Evaluation of the digamma function for
!                     double precision arguments
!
!                           -----------
!
!     dpsi(a) is assigned the value 0 when the digamma function CANNOT
!     be computed.
!
!-----------------------------------------------------------------------
!     Written by Alfred H. Morris, Jr.
!          Naval Surface Warfare Center
!          Dahlgren, Virginia
!-----------------------------------------------------------------------
!
!     The series for dpsi on the interval 0.0 to 1.0 was derived
!     by Wayne Fullerton (Los Alamos National Laboratory).
!
!                                  WITH WEIGHTED ERROR   5.79E-32
!                                   log weighted error  31.24
!                         significant figures required  30.93
!                              decimal places required  32.05
!
!     The series for  a .GE. 10  was derived by A.H. Morris from
!     the Chebyshev series in the SLATEC library obtained by Wayne
!     Fullerton (Los Alamos).
!
!-----------------------------------------------------------------------
!----------------------------
data pi /3.1415926535897932384626433832795d0/
data x0 /.46163214496836234126265954232572d0/
!----------------------------
data c(1)  / -.38057080835217921520437677667039d-01/, &
   & c(2)  /  .49141539302938712748204699654277d+00/, &
   & c(3)  / -.56815747821244730242892064734081d-01/, &
   & c(4)  /  .83578212259143131362775650747862d-02/, &
   & c(5)  / -.13332328579943425998079274172393d-02/, &
   & c(6)  /  .22031328706930824892872397979521d-03/, &
   & c(7)  / -.37040238178456883592889086949229d-04/, &
   & c(8)  /  .62837936548549898933651418717690d-05/, &
   & c(9)  / -.10712639085061849855283541747074d-05/, &
   & c(10) /  .18312839465484165805731589810378d-06/
data c(11) / -.31353509361808509869005779796885d-07/, &
   & c(12) /  .53728087762007766260471919143615d-08/, &
   & c(13) / -.92116814159784275717880632624730d-09/, &
   & c(14) /  .15798126521481822782252884032823d-09/, &
   & c(15) / -.27098646132380443065440589409707d-10/, &
   & c(16) /  .46487228599096834872947319529549d-11/, &
   & c(17) / -.79752725638303689726504797772737d-12/, &
   & c(18) /  .13682723857476992249251053892838d-12/, &
   & c(19) / -.23475156060658972717320677980719d-13/, &
   & c(20) /  .40276307155603541107907925006281d-14/
data c(21) / -.69102518531179037846547422974771d-15/, &
   & c(22) /  .11856047138863349552929139525768d-15/, &
   & c(23) / -.20341689616261559308154210484223d-16/, &
   & c(24) /  .34900749686463043850374232932351d-17/, &
   & c(25) / -.59880146934976711003011081393493d-18/, &
   & c(26) /  .10273801628080588258398005712213d-18/, &
   & c(27) / -.17627049424561071368359260105386d-19/, &
   & c(28) /  .30243228018156920457454035490133d-20/, &
   & c(29) / -.51889168302092313774286088874666d-21/, &
   & c(30) /  .89027730345845713905005887487999d-22/
data c(31) / -.15274742899426728392894971904000d-22/, &
   & c(32) /  .26207314798962083136358318079999d-23/, &
   & c(33) / -.44964642738220696772598388053333d-24/, &
   & c(34) /  .77147129596345107028919364266666d-25/, &
   & c(35) / -.13236354761887702968102638933333d-25/, &
   & c(36) /  .22709994362408300091277311999999d-26/, &
   & c(37) / -.38964190215374115954491391999999d-27/, &
   & c(38) /  .66851981388855302310679893333333d-28/, &
   & c(39) / -.11469986654920864872529919999999d-28/, &
   & c(40) /  .19679385886541405920515413333333d-29/
data c(41) / -.33764488189750979801907200000000d-30/, &
   & c(42) /  .57930703193214159246677333333333d-31/
!----------------------------
data p(1)  / .833333333333333333333333333147d-03/, &
   & p(2)  /-.833333333333333333333317475057d-06/, &
   & p(3)  / .396825396825396825343072884056d-08/, &
   & p(4)  /-.416666666666666570859890514548d-10/, &
   & p(5)  / .757575757575654146210665696401d-12/, &
   & p(6)  /-.210927960920616064592099772274d-13/, &
   & p(7)  / .833333329719356554828382131321d-15/, &
   & p(8)  /-.443259676504784387819140445894d-16/, &
   & p(9)  / .305392145578967948828783519552d-17/, &
   & p(10) /-.264499326810660590871410866039d-18/
data p(11) / .280568932535744579536244004181d-19/, &
   & p(12) /-.351388195869099967789469969066d-20/, &
   & p(13) / .476233402067211507540059750399d-21/, &
   & p(14) /-.575024569953144855161645738666d-22/, &
   & p(15) / .416180125797657207803740160000d-23/
!----------------------------
!
!     ****** xmax, max, and eps are machine dependent constants.
!            Xmax is the largest positive real number that may
!            be used, max is the largest positive integer that
!            may be used, and eps is the smallest real number
!            such that 1.D0 + eps .GT. 1.D0.
!
max = ipmpar(3)
eps = dpmpar(1)
xmax = dpmpar(3)
!
!----------------------------
dpsi = 0.d0
x = a
if (dabs(a) .ge. 10.d0) go to 60
!-----------------------------------------------------------------------
!             Evaluation of dpsi(a) for dabs(a) .LT. 10
!-----------------------------------------------------------------------
t = 0.d0
n = x
n = n - 1
!
!     Let t be the sum of 1/(a-j) when a .GE. 2
!
if (n) 20,12,10
10 do 11 j = 1,n
   x = x - 1.d0
   t = 1.d0/x + t
11 continue
12 x = x - 1.d0
go to 40
!
!     Check if 1/a can overflow
!
20 if (dabs(a) .ge. 1.d-35) go to 30
if (dabs(a)*xmax .le. 1.000000001d0) return
!
!     Let t be the sum of -1/(a+j) when a .LT. 1
!
30 t = -1.d0/a
if (a .gt. 0.d0) go to 40
n = - n - 1
if (n .eq. 0) go to 32
do 31 j = 1,n
   x = x + 1.d0
   if (x .eq. 0.d0) return
   t = t - 1.d0/x
31 continue
32 x = (x + 0.5d0) + 0.5d0
if (x .eq. 0.d0) return
t = t - 1.d0/x
!
!     COMPUTE  t + dpsi(1 + x)  FOR 0 .LE. x .LT. 1
!
40 if (dabs(x - x0) .gt. 2.d-2) go to 50
dpsi = t + dpsi0(1.d0 + x)
return
50 k = 42
if (eps .gt. 1.d-20) k = 28
dpsi = t + dcsevl (2.d0*x - 1.d0, c, k)
return
!-----------------------------------------------------------------------
!           Evaluation of dpsi(a) for dabs(a) .GE. 10
!-----------------------------------------------------------------------
60 if (a .gt. 0.d0) go to 70
t = max
if (dabs(a) .ge. dmin1(t, 1.d0/eps)) return
!
!     Set w = pi*cot(pi*a) when A is negative
!
k = dabs(a)
t = a + k
if (t .eq. 0.d0) return
if (t .le. -0.5d0) t = 1.d0 + t
t = pi*t
w = pi*(dcos(t)/dsin(t))
x = 1.d0 - x
!
!     Compute the modified asymptotic sum
!
70 t = (10.d0/x)**2
s = p(15)
do j = 1,14
   l = 15 - j
   s = p(l) + t*s
end do
s = 0.5d0/x + t*s
!
!     Final assembly
!
dpsi = dlog(x) - s
if (a .lt. 0.d0) dpsi = dpsi - w
return
end function dpsi

double precision function dpsi0 (x)
implicit none
double precision, intent(in) :: x
integer :: i, l, n, nm1
double precision :: a(20), h
double precision :: w
double precision :: dk1, dk2, dk3, db, db2, dx
!-----------------------------------------------------------------------
!
!            Taylor series expansion of psi(x) around X0,
!                  where X0 is the zero of psi(x).
!
!-------------------------
!     Written by A.H. Morris
!        Naval Surface Warfare Center
!        Dahlgren, Virginia
!-----------------------------------------------------------------------
!-------------------------
data dk1 /100442596182.d0/, dk2 /51069247913.d0/, &
   & dk3 /53827985572.d0/
data db  /68719476736.d0/
data dx  /.28939299282041499433886199389507989269636d-32/
!-------------------------
data a(1)  / .967672245447621170427444761710d+00/, &
   & a(2)  /-.442763168983592106092865281853d+00/, &
   & a(3)  / .258499760955651010624401385701d+00/, &
   & a(4)  /-.163942705442406527504251292747d+00/, &
   & a(5)  / .107824050691262365757182948867d+00/, &
   & a(6)  /-.721995612564547109261217836051d-01/, &
   & a(7)  / .488042881641431072250925255079d-01/, &
   & a(8)  /-.331611264748473592922583984045d-01/, &
   & a(9)  / .225976482322181046596248251178d-01/, &
   & a(10) /-.154247659049489591388003168412d-01/
data a(11) / .105387916166121753881240498824d-01/, &
   & a(12) /-.720453438635686824097047437040d-02/, &
   & a(13) / .492678139572985344635426640268d-02/, &
   & a(14) /-.336980165543932808279285672353d-02/, &
   & a(15) / .230512632673492783693838028298d-02/, &
   & a(16) /-.157693677143019725927093497173d-02/, &
   & a(17) / .107882520191629658069191777474d-02/, &
   & a(18) /-.738070938996005129566047389379d-03/, &
   & a(19) / .504953265834602035177398177463d-03/, &
   & a(20) /-.345468025106307699555567970882d-03/
!-------------------------
!
!     Set  h = x - X0  where X0 is the zero of psi(x). X0 has the
!     approximate 60 digit value ...
!
!      1.4616321449683623412 62659542325721328468 19620400644635129598
!
!     A more accurate value is given by ...
!
!            x0 = dk1/8**12 + dk2/8**24 + dk3/8**36 + dx
!
!     The following code should yield the correct value for h if A
!     binary, octal, or hexadecimal double precision arithmetic is
!     being used.
!
db2 = db*db
h = (((x - dk1/db) - dk2/db2) - dk3/(db*db2)) - dx
!
!-------------------------
!
n = 20
nm1 = n - 1
w = a(n)
do 10 i = 1,nm1
   l = n - i
   w = a(l) + h*w
10 continue
dpsi0 = h*w
return
end function dpsi0

subroutine psidf (x, n, m, ans, iflag)
implicit none
integer, intent(out) :: iflag
integer, intent(in) :: m, n
real, intent(in) :: x
real, intent(inout) :: ans(m)
integer :: i, j, k, mx, nmax, nn, np, nx
real :: alpha, arg, beta, c, den, elim, eps, fln, fn, fnp, fns, &
   & fx, nd, rxsq, s, t, ta, tk, tol, tols, tss, tst, tt, t1, t2, wdtol
real :: xdmln, xdmy, xinc, xln, xm, xmin
real :: b(22), trm(22), trmr(100)
real :: epsln, exparg, spmpar
!-----------------------------------------------------------------------
!
!         psidf computes m member sequences of scaled derivatives of
!         the psi function
!
!                w(k,x)=(-1)**(k+1)*psi(k,x)/gamma(k+1)
!
!         k=n,...,n+m-1 where psi(k,x) is the k-TH derivative of the
!         psi function.
!
!         The BASIC method of evaluation is the asymptotic expansion
!         for large x.GE.xmin followed by backward recursion on a two
!         term recursion relation
!
!                  W(x+1) + x**(-n-1) = W(x).
!
!         This is supplemented by a series
!
!                  sum( (x+k)**(-n-1) , k=0,1,2,... )
!
!         Which converges rapidly for large n. both xmin and the
!         number of terms of the series are calculated from the unit
!         round off of the machine environment.
!
!         The nominal computational accuracy is the maximum of unit
!         roundoff (=spmpar(1)) and 1.0E-18 since critical constants
!         are given to only 18 digits.
!
!     Description of arguments
!
!         Input
!
!           x      - ARGUMENT, x .GT. 0.0
!
!           n      - First member of the sequence, n .GE. 0
!
!           m      - Number of members of the sequence, m .GE. 1
!
!         Output
!
!           ans    - A vector of length at least m whose first m
!                    components are the scaled derivatives.
!
!           iflag  - A variable which reports the status of the
!                    results.
!                    iflag = 0 The desired values were obtained.
!                    iflag = 1 An input error was detected.
!                    iflag = 2 Overflow. x too small or n+m-1
!                              too large.
!                    iflag = 3 Underflow. x too large or n+m-1
!                              too large.
!                    iflag = 4 n+m-1 is too large for the current
!                              value of x. this setting will not
!                              occur when n+m-1 .LE. 100.
!
!-----------------------------------------------------------------------
!     Written by Donald E. Amos
!         Sandia Laboratories
!         June 1982
!     modified by A. H. Morris (NSWC), 1990.
!
!     References ...
!
!     (1) ACM Trans. Math Software, 1983.
!     (2) Handbook of mathematical functions, AMS 55, national bureau
!         of standards by m. Abramowitz and I.A. Stegun, 1964, PP.
!         258-260, equations 6.3.5, 6.3.18, 6.4.6, 6.4.9, 6.4.10.
!-----------------------------------------------------------------------
!------------------------
!     c = 1/ln(10)
!------------------------
data c /.43429/
data nmax /100/
!-----------------------------------------------------------------------
!                        Bernoulli numbers
!-----------------------------------------------------------------------
data b(1), b(2), b(3), b(4), b(5), b(6), b(7), b(8), b(9), b(10), &
   & b(11), b(12), b(13), b(14), b(15), b(16), b(17), b(18), b(19), &
   & b(20), b(21), b(22) /1.0, &
   & -5.00000000000000000e-01,1.66666666666666667e-01, &
   & -3.33333333333333333e-02,2.38095238095238095e-02, &
   & -3.33333333333333333e-02,7.57575757575757576e-02, &
   & -2.53113553113553114e-01,1.16666666666666667e+00, &
   & -7.09215686274509804e+00,5.49711779448621554e+01, &
   & -5.29124242424242424e+02,6.19212318840579710e+03, &
   & -8.65802531135531136e+04,1.42551716666666667e+06, &
   & -2.72982310678160920e+07,6.01580873900642368e+08, &
   & -1.51163157670921569e+10,4.29614643061166667e+11, &
   & -1.37116552050883328e+13,4.88332318973593167e+14, &
   & -1.92965793419400681e+16/
!------------------------
iflag = 0
if (x .le. 0.0 .or. n .lt. 0 .or. m .lt. 1) go to 300
!
nn = n + m - 1
fn = float(nn)
fnp = fn + 1.0
eps = spmpar(1)
wdtol = amax1(0.5*eps, 0.5e-18)
!-----------------------------------------------------------------------
!     elim = Approximate exponential over and underflow limit
!-----------------------------------------------------------------------
elim = amin1(exparg(0), abs(exparg(1))) - 6.906
xln = alog(x)
t = fnp*xln
!-----------------------------------------------------------------------
!     Overflow and underflow test for small and large x
!-----------------------------------------------------------------------
if (abs(t) .gt. elim) go to 310
if (x .lt. wdtol) go to 260
!-----------------------------------------------------------------------
!     Compute xmin and the number of terms of the series, fln+1
!-----------------------------------------------------------------------
nd = -c*epsln(0)
nd = amin1(nd,18.0)
fln = nd - 3.0
alpha = 3.5 + 0.4*fln
beta = 0.21 + fln*(0.0006038*fln + 0.008677)
xm = alpha + beta*fn
mx = int(xm) + 1
xmin = float(mx)
!
if (n .eq. 0) go to 50
xm = -2.302*nd - amin1(0.0,xln)
fns = float(n)
arg = xm/fns
arg = amin1(0.0,arg)
eps = exp(arg)
xm = 1.0 - eps
if (abs(arg) .lt. 1.0e-3) xm = -arg
fln = x*xm/eps
xm = xmin - x
if (xm .gt. 7.0 .and. fln .lt. 15.0) go to 200
!
50 xdmy = x
xdmln = xln
xinc = 0.0
if (x .ge. xmin) go to 60
nx = int(x)
xinc = xmin - float(nx)
xdmy = x + xinc
xdmln = alog(xdmy)
60 continue
!-----------------------------------------------------------------------
!     Generate W(n+m-1,x) by the asymptotic expansion
!-----------------------------------------------------------------------
t = fn*xdmln
t1 = xdmln + xdmln
t2 = t + xdmln
tk = amax1(abs(t),abs(t1),abs(t2))
if (tk .gt. elim) go to 320
!
tss = exp(-t)
tt = 0.5/xdmy
t1 = tt
tst = wdtol*tt
if (nn .ne. 0) t1 = tt + 1.0/fn
rxsq = 1.0/(xdmy*xdmy)
ta = 0.5*rxsq
t = fnp*ta
s = t*b(3)
if (abs(s) .lt. tst) go to 80
!
tk = 2.0
do k = 4,22
   t = t*((tk + fn + 1.0)/(tk + 1.0))*((tk + fn)/(tk + 2.0))*rxsq
   trm(k) = t*b(k)
   if (abs(trm(k)) .lt. tst) go to 80
   s = s + trm(k)
   tk = tk + 2.0
end do
!
80 s = (s + t1)*tss
if (xinc .eq. 0.0) go to 100
!-----------------------------------------------------------------------
!     Backward recur from xdmy to x
!-----------------------------------------------------------------------
nx = int(xinc)
np = nn + 1
if (nx .gt. nmax) go to 330
if (nn .eq. 0) go to 160
xm = xinc - 1.0
fx = x + xm
!-----------------------------------------------------------------------
!     This loop should not be changed. FX is accurate when x is small
!-----------------------------------------------------------------------
do i = 1,nx
   trmr(i) = fx**(-np)
   s = s + trmr(i)
   xm = xm - 1.0
   fx = x + xm
end do
!
100 ans(m) = s
if (fn .eq. 0.0) go to 180
!-----------------------------------------------------------------------
!     Generate lower derivatives, j.LT.n+m-1
!-----------------------------------------------------------------------
if (m .eq. 1) return
do j = 2,m
   fnp = fn
   fn = fn - 1.0
   tss = tss*xdmy
   t1 = tt
   if (fn .ne. 0.0) t1 = tt + 1.0/fn
   t = fnp*ta
   s = t*b(3)
   if (abs(s) .lt. tst) go to 120
!
   tk = 3.0e0 + fnp
   do k = 4,22
      trm(k) = trm(k)*fnp/tk
      if (abs(trm(k)) .lt. tst) go to 120
      s = s + trm(k)
      tk = tk + 2.0
   end do
!
120 s = (s + t1)*tss
   if (xinc .eq. 0.0) go to 140
   if (fn .eq. 0.0) go to 160
   xm = xinc - 1.0
   fx = x + xm
   do i = 1,nx
      trmr(i) = trmr(i)*fx
      s = s + trmr(i)
      xm = xm - 1.0
      fx = x + xm
   end do
!
140 mx = m - j + 1
   ans(mx) = s
   if (fn .eq. 0.0) go to 180
end do
return
!-----------------------------------------------------------------------
!     Recursion for n = 0
!-----------------------------------------------------------------------
160 do i = 1,nx
   s = s + 1.0/(x + float(nx - i))
end do
!
180 ans(1) = s - xdmln
return
!-----------------------------------------------------------------------
!     Compute by series (x+k)**(-(n+1)) , k=0,1,2,...
!-----------------------------------------------------------------------
200 nn = int(fln) + 1
np = n + 1
t1 = (fns + 1.0)*xln
t = exp(-t1)
s = t
den = x
do i = 1,nn
   den = den + 1.0
   trm(i) = den**(-np)
   s = s + trm(i)
end do
ans(1) = s
if (m .eq. 1) return
!-----------------------------------------------------------------------
!     Generate higher derivatives, j .GT. n
!-----------------------------------------------------------------------
tol = wdtol/5.0
do j = 2,m
   t = t/x
   s = t
   tols = t*tol
   den = x
   do i = 1,nn
      den = den + 1.0
      trm(i) = trm(i)/den
      s = s + trm(i)
      if (trm(i) .lt. tols) go to 240
   end do
240 ans(j) = s
end do
return
!-----------------------------------------------------------------------
!     Small x .LT. unit round off
!-----------------------------------------------------------------------
260 ans(1) = x**(-n - 1)
if (m .eq. 1) return
k = 1
do i = 2,m
   ans(k + 1) = ans(k)/x
   k = k + 1
end do
return
!-----------------------------------------------------------------------
!     Error return
!-----------------------------------------------------------------------
300 iflag = 1
return
!
310 if (t .gt. 0.0) go to 320
iflag = 2
return
!
320 iflag = 3
return
!                            Increase the dimension of trmr(nmax)
330 iflag = 4
return
end subroutine psidf

real function betaln (a0, b0)
implicit none
real, intent(in) :: a0, b0
integer :: i, n
real :: a, b, c, e, h, u, v, w, z
real :: algdiv, alnrel, bcorr, gamln, gsumln
!-----------------------------------------------------------------------
!     Evaluation of the logarithm of the beta function
!-----------------------------------------------------------------------
!     e = 0.5*ln(2*pi)
!--------------------------
data e /.918938533204673/
!--------------------------
a = amin1(a0,b0)
b = amax1(a0,b0)
if (a .ge. 8.0) go to 60
if (a .ge. 1.0) go to 20
!-----------------------------------------------------------------------
!                   Procedure when a .LT. 1
!-----------------------------------------------------------------------
if (b .ge. 8.0) go to 10
betaln = gamln(a) + (gamln(b) - gamln(a + b))
return
10 betaln = gamln(a) + algdiv(a,b)
return
!-----------------------------------------------------------------------
!                Procedure when 1 .LE. a .LT. 8
!-----------------------------------------------------------------------
20 if (a .gt. 2.0) go to 30
if (b .gt. 2.0) go to 21
betaln = gamln(a) + gamln(b) - gsumln(a,b)
return
21 w = 0.0
if (b .lt. 8.0) go to 40
betaln = gamln(a) + algdiv(a,b)
return
!
!                Reduction of a when b .LE. 1000
!
30 if (b .gt. 1000.0) go to 50
n = a - 1.0
w = 1.0
do i = 1,n
   a = a - 1.0
   h = a/b
   w = w * (h/(1.0 + h))
end do
w = alog(w)
if (b .lt. 8.0) go to 40
betaln = w + gamln(a) + algdiv(a,b)
return
!
!                 Reduction of b when b .LT. 8
!
40 n = b - 1.0
z = 1.0
do i = 1,n
   b = b - 1.0
   z = z * (b/(a + b))
end do
betaln = w + alog(z) + (gamln(a) + (gamln(b) - gsumln(a,b)))
return
!
!                Reduction of a when b .GT. 1000
!
50 n = a - 1.0
w = 1.0
do i = 1,n
   a = a - 1.0
   w = w * (a/(1.0 + a/b))
end do
betaln = (alog(w) - n*alog(b)) + (gamln(a) + algdiv(a,b))
return
!-----------------------------------------------------------------------
!                   Procedure when a .GE. 8
!-----------------------------------------------------------------------
60 w = bcorr(a,b)
h = a/b
c = h/(1.0 + h)
u = -(a - 0.5)*alog(c)
v = b*alnrel(h)
if (u .le. v) go to 61
betaln = (((-0.5*alog(b) + e) + w) - v) - u
return
61 betaln = (((-0.5*alog(b) + e) + w) - u) - v
return
end function betaln

real function gsumln (a, b)
implicit none
real, intent(in) :: a, b
real :: x
real :: alnrel, gamln1
!-----------------------------------------------------------------------
!          Evaluation of the function ln(gamma(a + b))
!          FOR 1 .LE. a .LE. 2  AND  1 .LE. b .LE. 2
!-----------------------------------------------------------------------
x = dble(a) + dble(b) - 2.d0
if (x .gt. 0.25) go to 10
gsumln = gamln1(1.0 + x)
return
10 if (x .gt. 1.25) go to 20
gsumln = gamln1(x) + alnrel(x)
return
20 gsumln = gamln1(x - 1.0) + alog(x*(1.0 + x))
return
end function gsumln

real function bcorr (a0, b0)
implicit none
real, intent(in) :: a0, b0
real :: a, b, c, c0, c1, c2, c3, c4, c5, h, s11, s3, s5, s7, s9, &
   & t, w, x, x2
!-----------------------------------------------------------------------
!
!     Evaluation of  del(a0) + del(b0) - Del(a0 + b0)  where
!     LN(gamma(a)) = (a - 0.5)*LN(a) - a + 0.5*LN(2*PI) + DEL(a).
!     It is assumed that a0 .GE. 8 and b0 .GE. 8.
!
!-----------------------------------------------------------------------
data c0/.833333333333333e-01/, c1/-.277777777760991e-02/, &
   & c2/.793650666825390e-03/, c3/-.595202931351870e-03/, &
   & c4/.837308034031215e-03/, c5/-.165322962780713e-02/
!------------------------
a = amin1(a0, b0)
b = amax1(a0, b0)
!
h = a/b
c = h/(1.0 + h)
x = 1.0/(1.0 + h)
x2 = x*x
!
!                SET SN = (1 - X**N)/(1 - X)
!
s3 = 1.0 + (x + x2)
s5 = 1.0 + (x + x2*s3)
s7 = 1.0 + (x + x2*s5)
s9 = 1.0 + (x + x2*s7)
s11 = 1.0 + (x + x2*s9)
!
!                SET W = DEL(b) - DEL(a + b)
!
t = (1.0/b)**2
w = ((((c5*s11*t + c4*s9)*t + c3*s7)*t + c2*s5)*t + c1*s3)*t + c0
w = w*(c/b)
!
!                   Compute  del(a) + W
!
t = (1.0/a)**2
bcorr = (((((c5*t + c4)*t + c3)*t + c2)*t + c1)*t + c0)/a + w
return
end function bcorr

real function algdiv (a, b)
implicit none
real, intent(in) :: a, b
real :: alnrel
real :: c, c0, c1, c2, c3, c4, c5, d, h, s11, s3, s5, s7, s9, t, &
   & u, v, w, x, x2
!-----------------------------------------------------------------------
!
!     Computation of LN(gamma(b)/gamma(a+b)) when b .GE. 8
!
!                         --------
!
!     In this algorithm, del(X) is the function defined by
!     LN(gamma(X)) = (X - 0.5)*LN(X) - X + 0.5*LN(2*PI) + DEL(X).
!
!-----------------------------------------------------------------------
data c0/.833333333333333e-01/, c1/-.277777777760991e-02/, &
   & c2/.793650666825390e-03/, c3/-.595202931351870e-03/, &
   & c4/.837308034031215e-03/, c5/-.165322962780713e-02/
!------------------------
if (a .le. b) go to 10
h = b/a
c = 1.0/(1.0 + h)
x = h/(1.0 + h)
d = a + (b - 0.5)
go to 20
10 h = a/b
c = h/(1.0 + h)
x = 1.0/(1.0 + h)
d = b + (a - 0.5)
!
!                SET SN = (1 - X**N)/(1 - X)
!
20 x2 = x*x
s3 = 1.0 + (x + x2)
s5 = 1.0 + (x + x2*s3)
s7 = 1.0 + (x + x2*s5)
s9 = 1.0 + (x + x2*s7)
s11 = 1.0 + (x + x2*s9)
!
!                SET W = DEL(b) - DEL(a + b)
!
t = (1.0/b)**2
w = ((((c5*s11*t + c4*s9)*t + c3*s7)*t + c2*s5)*t + c1*s3)*t + c0
w = w*(c/b)
!
!                    Combine the results
!
u = d*alnrel(a/b)
v = a*(alog(b) - 1.0)
if (u .le. v) go to 30
algdiv = (w - v) - u
return
30 algdiv = (w - u) - v
return
end function algdiv

double precision function dbetln (a0, b0)
implicit none
double precision, intent(in) :: a0, b0
integer :: i, n
double precision :: a, b, c, e, h, sn, u, v, w, z
double precision :: dbcorr, dgamln, dgsmln, dlgdiv, dlnrel
!-----------------------------------------------------------------------
!     Evaluation of the logarithm of the beta function
!-----------------------------------------------------------------------
!--------------------------
!     e = 0.5*ln(2*pi)
!--------------------------
data e /.9189385332046727417803297364056d0/
!--------------------------
a = dmin1(a0,b0)
b = dmax1(a0,b0)
if (a .ge. 10.d0) go to 60
if (a .ge. 1.d0) go to 20
!-----------------------------------------------------------------------
!                   Procedure when a .LT. 1
!-----------------------------------------------------------------------
if (b .ge. 10.d0) go to 10
dbetln = dgamln(a) + (dgamln(b) - dgamln(a + b))
return
10 dbetln = dgamln(a) + dlgdiv(a,b)
return
!-----------------------------------------------------------------------
!               Procedure when 1 .LE. a .LT. 10
!-----------------------------------------------------------------------
20 if (a .gt. 2.d0) go to 30
if (b .gt. 2.d0) go to 21
dbetln = dgamln(a) + dgamln(b) - dgsmln(a,b)
return
21 w = 0.d0
if (b .lt. 10.d0) go to 40
dbetln = dgamln(a) + dlgdiv(a,b)
return
!
!               Reduction of a when b .LE. 1000
!
30 if (b .gt. 1.d3) go to 50
n = a - 1.d0
w = 1.d0
do i = 1,n
   a = a - 1.d0
   h = a/b
   w = w * (h/(1.d0 + h))
end do
w = dlog(w)
if (b .lt. 10.d0) go to 40
dbetln = w + dgamln(a) + dlgdiv(a,b)
return
!
!                Reduction of b when b .LT. 10
!
40 n = b - 1.d0
z = 1.d0
do i = 1,n
   b = b - 1.d0
   z = z * (b/(a + b))
end do
dbetln = w + dlog(z) + (dgamln(a) + (dgamln(b) - dgsmln(a,b)))
return
!
!               Reduction of a when b .GT. 1000
!
50 n = a - 1.d0
w = 1.d0
do i = 1,n
   a = a - 1.d0
   w = w*(a/(1.d0 + a/b))
end do
sn = n
dbetln = (dlog(w) - sn*dlog(b)) + (dgamln(a) + dlgdiv(a,b))
return
!-----------------------------------------------------------------------
!                  Procedure when a .GE. 10
!-----------------------------------------------------------------------
60 w = dbcorr(a,b)
h = a/b
c = h/(1.d0 + h)
u = -(a - 0.5d0)*dlog(c)
v = b*dlnrel(h)
if (u .le. v) go to 61
dbetln = (((-0.5d0*dlog(b) + e) + w) - v) - u
return
61 dbetln = (((-0.5d0*dlog(b) + e) + w) - u) - v
return
end function dbetln

double precision function dgsmln (a, b)
implicit none
!-----------------------------------------------------------------------
!          Evaluation of the function ln(gamma(a + b))
!          FOR 1 .LE. a .LE. 2  AND  1 .LE. b .LE. 2
!-----------------------------------------------------------------------
double precision, intent(in) :: a, b
double precision :: x
double precision :: dgmln1, dlnrel
!
x = (a - 1.d0) + (b - 1.d0)
if (x .gt. 0.5d0) go to 10
dgsmln = dgmln1(1.d0 + x)
return
10 if (x .gt. 1.5d0) go to 20
dgsmln = dgmln1(x) + dlnrel(x)
return
20 dgsmln = dgmln1(x - 1.d0) + dlog(x*(1.d0 + x))
return
end function dgsmln

double precision function dbcorr (a0, b0)
implicit none
double precision, intent(in) :: a0, b0
integer :: j, k
double precision :: a, b, c, e(15), h, s(15), t, w, x, x2, z
!-----------------------------------------------------------------------
!
!     Evaluation of del(a) + del(b0) - Del(a) + b0) where
!     LN(gamma(x)) = (x - 0.5)*LN(x) - x + 0.5*LN(2*PI) + DEL(x).
!     It is assumed that a0 .GE. 10 and b0 .GE. 10.
!
!                         --------
!
!     The series for del(x), which applies for x .GE. 10, was
!     derived by A.H. Morris from the Chebyshev series in the
!     SLATEC library obtained by Wayne Fullerton (Los Alamos).
!
!-----------------------------------------------------------------------
!--------------------------
data e(1)  / .833333333333333333333333333333d-01/, &
   & e(2)  /-.277777777777777777777777752282d-04/, &
   & e(3)  / .793650793650793650791732130419d-07/, &
   & e(4)  /-.595238095238095232389839236182d-09/, &
   & e(5)  / .841750841750832853294451671990d-11/, &
   & e(6)  /-.191752691751854612334149171243d-12/, &
   & e(7)  / .641025640510325475730918472625d-14/, &
   & e(8)  /-.295506514125338232839867823991d-15/, &
   & e(9)  / .179643716359402238723287696452d-16/, &
   & e(10) /-.139228964661627791231203060395d-17/
data e(11) / .133802855014020915603275339093d-18/, &
   & e(12) /-.154246009867966094273710216533d-19/, &
   & e(13) / .197701992980957427278370133333d-20/, &
   & e(14) /-.234065664793997056856992426667d-21/, &
   & e(15) / .171348014966398575409015466667d-22/
!--------------------------
a = dmin1(a0, b0)
b = dmax1(a0, b0)
!
h = a/b
c = h/(1.d0 + h)
x = 1.d0/(1.d0 + h)
x2 = x*x
!
!        COMPUTE (1 - x**N)/(1 - x) FOR N = 1,3,5,...
!            Store these values in s(1),s(2),...
!
s(1) = 1.d0
do 10 j = 1,14
   s(j + 1) = 1.d0 + (x + x2*s(j))
10 continue
!
!                SET w = DEL(b) - DEL(a + b)
!
t = (10.d0/b)**2
w = e(15)*s(15)
do 20 j = 1,14
   k = 15 - j
   w = t*w + e(k)*s(k)
20 continue
w = w*(c/b)
!
!                    Compute  del(a) + w
!
t = (10.d0/a)**2
z = e(15)
do j = 1,14
   k = 15 - j
   z = t*z + e(k)
end do
dbcorr = z/a + w
return
end function dbcorr

double precision function dlgdiv (a, b)
implicit none
double precision, intent(in) :: a, b
integer :: j, k
double precision :: c, d, e(15), h, s(15), t, u, v, w, x, x2
double precision :: dlnrel
!-----------------------------------------------------------------------
!
!     Computation of LN(gamma(b)/gamma(a+b)) for b .GE. 10
!
!                         --------
!
!     dlgdiv uses a series for the function DEL(x) where
!     LN(gamma(x)) = (x - 0.5)*LN(x) - x + 0.5*LN(2*PI) + DEL(x).
!     The series for del(x), which applies for x .GE. 10, was
!     derived by A.H. Morris from the Chebyshev series in the
!     SLATEC library obtained by Wayne Fullerton (Los Alamos).
!
!-----------------------------------------------------------------------
!--------------------------
data e(1)  / .833333333333333333333333333333d-01/, &
   & e(2)  /-.277777777777777777777777752282d-04/, &
   & e(3)  / .793650793650793650791732130419d-07/, &
   & e(4)  /-.595238095238095232389839236182d-09/, &
   & e(5)  / .841750841750832853294451671990d-11/, &
   & e(6)  /-.191752691751854612334149171243d-12/, &
   & e(7)  / .641025640510325475730918472625d-14/, &
   & e(8)  /-.295506514125338232839867823991d-15/, &
   & e(9)  / .179643716359402238723287696452d-16/, &
   & e(10) /-.139228964661627791231203060395d-17/
data e(11) / .133802855014020915603275339093d-18/, &
   & e(12) /-.154246009867966094273710216533d-19/, &
   & e(13) / .197701992980957427278370133333d-20/, &
   & e(14) /-.234065664793997056856992426667d-21/, &
   & e(15) / .171348014966398575409015466667d-22/
!--------------------------
if (a .le. b) go to 10
h = b/a
c = 1.d0/(1.d0 + h)
x = h/(1.d0 + h)
d = a + (b - 0.5d0)
go to 20
10 h = a/b
c = h/(1.d0 + h)
x = 1.d0/(1.d0 + h)
d = b + (a - 0.5d0)
!
!        COMPUTE (1 - x**N)/(1 - x) FOR N = 1,3,5,...
!            Store these values in s(1),s(2),...
!
20 x2 = x*x
s(1) = 1.d0
do 21 j = 1,14
   s(j + 1) = 1.d0 + (x + x2*s(j))
21 continue
!
!                SET w = DEL(b) - DEL(a + b)
!
t = (10.d0/b)**2
w = e(15)*s(15)
do j = 1,14
   k = 15 - j
   w = t*w + e(k)*s(k)
end do
w = w*(c/b)
!
!                    Combine the results
!
u = d*dlnrel(a/b)
v = a*(dlog(b) - 1.d0)
if (u .le. v) go to 40
dlgdiv = (w - v) - u
return
40 dlgdiv = (w - u) - v
return
end function dlgdiv

subroutine gratio (a, x, ans, qans, ind)
implicit none
integer, intent(in) :: ind
real, intent(in) :: a
real, intent(inout) :: ans, qans
real, intent(in) :: x
integer :: i, iop, m, max, n
real :: a2n, a2nm1, acc, alog10, amn, apn, b2n, b2nm1, c, c0, c1, &
   & c2, c3, c4, c5, c6, c7, c8, d00, d10, d20, d30, d40, d50, d60, &
   & d70, d80, e, g, h, r, rt2pin, rta, rtpi, rtx, s, sum, t, tol, &
   & twoa, u, w, y, z
real :: rexp
real :: gam1
real :: erfc1
real :: rcomp
real :: rlog
real :: spmpar
real :: j, l, acc0(3), big(3), e0(3), x0(3), wk(20)
real :: a0(4), a1(4), a2(2), a3(2), a4(2), a5(2), a6(2), a7(2), &
   & a8(2)
real :: b0(6), b1(4), b2(5), b3(5), b4(4), b5(3), b6(2), b7(2)
real :: d0(6), d1(4), d2(2), d3(2), d4(1), d5(1), d6(1)
!-----------------------------------------------------------------------
!
!        Evaluation of the incomplete gamma ratio functions
!                      P(a,x) AND Q(a,x)
!
!                        ----------
!
!     It is assumed that A and x are nonnegative, where A and x
!     are not both 0.
!
!     Ans and qans are variables. gratio assigns ans the value
!     P(a,x) and qans the value Q(a,x). Ind may be any integer.
!     If ind = 0 Then the user is requesting as much accuracy as
!     possible (up to 14 significant digits). Otherwise, if
!     ind = 1 Then accuracy is requested to within 1 unit of the
!     6-TH significant digit, and if ind .NE. 0,1 then accuracy
!     is requested to within 1 unit of the 3RD significant digit.
!
!     Error return ...
!
!        Ans is assigned the value 2 when A or x is negative,
!     when a*x = 0, or when P(a,x) and Q(a,x) are indeterminant.
!     P(a,x) and Q(a,x) are computationally indeterminant when
!     x is exceedingly close to A and A is extremely large.
!
!-----------------------------------------------------------------------
!     Written by Alfred H. Morris, Jr.
!        Naval Surface Warfare Center
!        Dahlgren, Virginia
!     revised ... DEC 1991
!-------------------------
!-------------------------
data acc0(1)/5.e-15/, acc0(2)/5.e-7/, acc0(3)/5.e-4/
data big(1)/25.0/, big(2)/14.0/, big(3)/10.0/
data e0(1)/.25e-3/, e0(2)/.25e-1/, e0(3)/.14/
data x0(1)/31.0/, x0(2)/17.0/, x0(3)/9.7/
!-------------------------
!     alog10 = ln(10)
!     rt2pin = 1/sqrt(2*pi)
!     rtpi   = sqrt(pi)
!-------------------------
data alog10/2.30258509299405/
data rt2pin/.398942280401433/
data rtpi  /1.77245385090552/
!-------------------------
!
!             Coefficients for minimax approximations
!                          FOR c0,...,C8
!
!-------------------------
data a0(1) /-.231272501940775e-02/, a0(2)/-.335378520024220e-01/, &
   & a0(3) /-.159840143443990e+00/, a0(4)/-.333333333333333e+00/
data b0(1)  /.633763414209504e-06/, b0(2)/-.939001940478355e-05/, &
   & b0(3)  /.239521354917408e-02/, b0(4)/ .376245718289389e-01/, &
   & b0(5)  /.238549219145773e+00/, b0(6)/ .729520430331981e+00/
!-------------------------
data a1(1) /-.398783924370770e-05/, a1(2)/-.587926036018402e-03/, &
   & a1(3) /-.491687131726920e-02/, a1(4)/-.185185185184291e-02/
data b1(1)  /.386325038602125e-02/, b1(2) /.506042559238939e-01/, &
   & b1(3)  /.283344278023803e+00/, b1(4) /.780110511677243e+00/
!-------------------------
data a2(1)  /.669564126155663e-03/, a2(2) /.413359788442192e-02/
data b2(1) /-.421924263980656e-03/, b2(2) /.650837693041777e-02/, &
   & b2(3) / .682034997401259e-01/, b2(4) /.339173452092224e+00/, &
   & b2(5) / .810647620703045e+00/
!-------------------------
data a3(1)  /.810586158563431e-03/, a3(2) /.649434157619770e-03/
data b3(1) /-.632276587352120e-03/, b3(2) /.905375887385478e-02/, &
   & b3(3) / .906610359762969e-01/, b3(4) /.406288930253881e+00/, &
   & b3(5) / .894800593794972e+00/
!-------------------------
data a4(1) /-.105014537920131e-03/, a4(2)/-.861888301199388e-03/
data b4(1)  /.322609381345173e-01/, b4(2) /.178295773562970e+00/, &
   & b4(3)  /.591353097931237e+00/, b4(4) /.103151890792185e+01/
!-------------------------
data a5(1) /-.435211415445014e-03/, a5(2)/-.336806989710598e-03/
data b5(1)  /.178716720452422e+00/, b5(2) /.600380376956324e+00/, &
   & b5(3)  /.108515217314415e+01/
!-------------------------
data a6(1) /-.182503596367782e-03/, a6(2) /.531279816209452e-03/
data b6(1)  /.345608222411837e+00/, b6(2) /.770341682526774e+00/
!-------------------------
data a7(1)  /.443219646726422e-03/, a7(2) /.344430064306926e-03/
data b7(1)  /.821824741357866e+00/, b7(2) /.115029088777769e+01/
!-------------------------
data a8(1)  /.878371203603888e-03/, a8(2)/-.686013280418038e-03/
!-------------------------
!
!              Coefficients for the Temme expansion
!
!-------------------------
data d00   /-.333333333333333e+00/, d0(1) / .833333333333333e-01/, &
   & d0(2) /-.148148148148148e-01/, d0(3) / .115740740740741e-02/, &
   & d0(4) / .352733686067019e-03/, d0(5) /-.178755144032922e-03/, &
   & d0(6) / .391926317852244e-04/
!-------------------------
data d10   /-.185185185185185e-02/, d1(1) /-.347222222222222e-02/, &
   & d1(2) / .264550264550265e-02/, d1(3) /-.990226337448560e-03/, &
   & d1(4) / .205761316872428e-03/
!-------------------------
data d20   / .413359788359788e-02/, d2(1) /-.268132716049383e-02/, &
   & d2(2) / .771604938271605e-03/
!-------------------------
data d30   / .649434156378601e-03/, d3(1) / .229472093621399e-03/, &
   & d3(2) /-.469189494395256e-03/
!-------------------------
data d40   /-.861888290916712e-03/, d4(1) / .784039221720067e-03/
!-------------------------
data d50   /-.336798553366358e-03/, d5(1) /-.697281375836586e-04/
!-------------------------
data d60   / .531307936463992e-03/, d6(1) /-.592166437353694e-03/
!-------------------------
data d70   / .344367606892378e-03/
!-------------------------
data d80   /-.652623918595309e-03/
!-------------------------
!
!     ****** E is a machine dependent constant. E is the smallest
!            floating point number for which 1.0 + E .GT. 1.0 .
!
e = spmpar(1)
!
!-------------------------
if (a .lt. 0.0 .or. x .lt. 0.0) go to 400
if (a .eq. 0.0 .and. x .eq. 0.0) go to 400
if (a*x .eq. 0.0) go to 331
!
iop = ind + 1
if (iop .ne. 1 .and. iop .ne. 2) iop = 3
acc = amax1(acc0(iop),e)
!
!            Select the appropriate algorithm
!
if (a .ge. 1.0) go to 10
if (a .eq. 0.5) go to 320
if (x .lt. 1.1) go to 110
r = rcomp(a,x)
if (r .eq. 0.0) go to 310
go to 170
!
10 if (a .ge. big(iop)) go to 20
if (a .gt. x .or. x .ge. x0(iop)) go to 30
twoa = a + a
m = int(twoa)
if (twoa .ne. float(m)) go to 30
i = m/2
if (a .eq. float(i)) go to 140
go to 150
!
20 l = x/a
if (l .eq. 0.0) go to 300
s = 0.5 + (0.5 - l)
z = rlog(l)
if (z .ge. 700.0/a) go to 330
y = a*z
rta = sqrt(a)
if (abs(s) .le.e0(iop)/rta) go to 250
if (abs(s) .le. 0.4) go to 200
!
30 r = rcomp(a,x)
if (r .eq. 0.0) go to 331
if (x .le. amax1(a,alog10)) go to 50
if (x .lt. x0(iop)) go to 170
go to 80
!
!                 Taylor series for P/R
!
50 apn = a + 1.0
t = x/apn
wk(1) = t
do n = 2,20
   apn = apn + 1.0
   t = t*(x/apn)
   if (t .le. 1.e-3) go to 60
   wk(n) = t
end do
n = 20
!
60 sum = t
tol = 0.5*acc
61 apn = apn + 1.0
t = t*(x/apn)
sum = sum + t
if (t .gt. tol) go to 61
!
max = n - 1
do 70 m = 1,max
   n = n - 1
   sum = sum + wk(n)
70 continue
ans = (r/a)*(1.0 + sum)
qans = 0.5 + (0.5 - ans)
return
!
!                 Asymptotic expansion
!
80 amn = a - 1.0
t = amn/x
wk(1) = t
do n = 2,20
   amn = amn - 1.0
   t = t*(amn/x)
   if (abs(t) .le. 1.e-3) go to 90
   wk(n) = t
end do
n = 20
!
90 sum = t
91 if (abs(t) .lt. acc) go to 100
amn = amn - 1.0
t = t*(amn/x)
sum = sum + t
go to 91
!
100 max = n - 1
do m = 1,max
   n = n - 1
   sum = sum + wk(n)
end do
qans = (r/x)*(1.0 + sum)
ans = 0.5 + (0.5 - qans)
return
!
!             Taylor series for P(a,x)/x**a
!
110 l = 3.0
c = x
sum = x/(a + 3.0)
tol = 3.0*acc/(a + 1.0)
111 l = l + 1.0
c = -c*(x/l)
t = c/(a + l)
sum = sum + t
if (abs(t) .gt. tol) go to 111
j = a*x*((sum/6.0 - 0.5/(a + 2.0))*x + 1.0/(a + 1.0))
!
z = a*alog(x)
h = gam1(a)
g = 1.0 + h
if (x .lt. 0.25) go to 120
if (a .lt. x/2.59) go to 135
go to 130
120 if (z .gt. -.13394) go to 135
!
130 w = exp(z)
ans = w*g*(0.5 + (0.5 - j))
qans = 0.5 + (0.5 - ans)
return
!
135 l = rexp(z)
w = 0.5 + (0.5 + l)
qans = (w*j - l)*g - h
if (qans .lt. 0.0) go to 310
ans = 0.5 + (0.5 - qans)
return
!
!             Finite sums for Q when a .GE. 1
!                 and 2*a is an integer
!
140 sum = exp(-x)
t = sum
n = 1
c = 0.0
go to 160
!
150 rtx = sqrt(x)
sum = erfc1(0,rtx)
t = exp(-x)/(rtpi*rtx)
n = 0
c = -0.5
!
160 if (n .eq. i) go to 161
n = n + 1
c = c + 1.0
t = (x*t)/c
sum = sum + t
go to 160
161 qans = sum
ans = 0.5 + (0.5 - qans)
return
!
!              Continued fraction expansion
!
170 tol = amax1(8.0*e,4.0*acc)
a2nm1 = 1.0
a2n = 1.0
b2nm1 = x
b2n = x + (1.0 - a)
c = 1.0
180 a2nm1 = x*a2n + c*a2nm1
b2nm1 = x*b2n + c*b2nm1
c = c + 1.0
t = c - a
a2n = a2nm1 + t*a2n
b2n = b2nm1 + t*b2n
!
a2nm1 = a2nm1/b2n
b2nm1 = b2nm1/b2n
a2n = a2n/b2n
b2n = 1.0
if (abs(a2n - a2nm1/b2nm1) .ge. tol*a2n) go to 180
!
qans = r*a2n
ans = 0.5 + (0.5 - qans)
return
!
200 if (abs(s) .le. 2.0*e .and. a*e*e .gt. 3.28e-3) go to 400
c = exp(-y)
w = 0.5*erfc1(1,sqrt(y))
u = 1.0/a
z = sqrt(z + z)
if (l .lt. 1.0) z = -z
if (iop - 2) 210,220,230
!
210 if (abs(s) .le. 1.e-3) go to 260
!
!            Using the minimax approximations
!
c0 = (((a0(1)*z + a0(2))*z + a0(3))*z + a0(4)) / ((((((b0(1)*z + &
   & b0(2))*z + b0(3))*z + b0(4))*z + b0(5))*z + b0(6))*z + 1.0)
c1 = (((a1(1)*z + a1(2))*z + a1(3))*z + a1(4)) / &
   & ((((b1(1)*z + b1(2))*z + b1(3))*z + b1(4))*z + 1.0)
c2 = (a2(1)*z + a2(2))/(((((b2(1)*z + b2(2))*z + b2(3))*z + &
   & b2(4))*z + b2(5))*z + 1.0)
c3 = (a3(1)*z + a3(2))/(((((b3(1)*z + b3(2))*z + b3(3))*z + &
   & b3(4))*z + b3(5))*z + 1.0)
c4 = (a4(1)*z + a4(2))/((((b4(1)*z + b4(2))*z + b4(3))*z + &
   & b4(4))*z + 1.0)
c5 = (a5(1)*z + a5(2))/(((b5(1)*z + b5(2))*z + b5(3))*z + 1.0)
c6 = (a6(1)*z + a6(2))/((b6(1)*z + b6(2))*z + 1.0)
c7 = (a7(1)*z + a7(2))/((b7(1)*z + b7(2))*z + 1.0)
c8 = a8(1)*z + a8(2)
t = (((((((c8*u + c7)*u + c6)*u + c5)*u + c4)*u + c3)*u + &
   & c2)*u + c1)*u + c0
go to 240
!
!                    Temme expansion
!
220 c0 = (((((d0(6) * z + d0(5)) * z + d0(4)) * z + d0(3)) * z &
   & + d0(2)) * z + d0(1)) * z + d00
c1 = (((d1(4) * z + d1(3)) * z + d1(2)) * z + d1(1)) * z &
   & + d10
c2 = d2(1) * z + d20
t = (c2*u + c1)*u + c0
go to 240
!
230 t = ((d0(3) * z + d0(2)) * z + d0(1)) * z + d00
!
240 if (l .lt. 1.0) go to 241
qans = c*(w + rt2pin*t/rta)
ans = 0.5 + (0.5 - qans)
return
241 ans = c*(w - rt2pin*t/rta)
qans = 0.5 + (0.5 - ans)
return
!
!               TEMME EXPANSION FOR l = 1
!
250 if (a*e*e .gt. 3.28e-3) go to 400
c = 0.5 + (0.5 - y)
w = (0.5 - sqrt(y)*(0.5 + (0.5 - y/3.0))/rtpi)/c
u = 1.0/a
z = sqrt(z + z)
if (l .lt. 1.0) z = -z
if (iop - 2) 260,270,280
!
260 c0 = ((d0(3) * z + d0(2)) * z + d0(1)) * z + d00
c1 = ((d1(3) * z + d1(2)) * z + d1(1)) * z + d10
c2 = (d2(2) * z + d2(1)) * z + d20
c3 = (d3(2) * z + d3(1)) * z + d30
c4 = d4(1) * z + d40
c5 = d5(1) * z + d50
c6 = d6(1) * z + d60
t = (((((((d80*u + d70)*u + c6)*u + c5)*u + c4)*u + c3)*u &
   & + c2)*u + c1)*u + c0
go to 240
!
270 c0 = (d0(2) * z + d0(1)) * z + d00
c1 = d1(1) * z + d10
t = (d20*u + c1)*u + c0
go to 240
!
280 t = d0(1) * z + d00
go to 240
!
!                     Special cases
!
300 ans = 0.0
qans = 1.0
return
!
310 ans = 1.0
qans = 0.0
return
!
320 if (x .ge. 0.25) go to 321
ans = erf(sqrt(x))
qans = 0.5 + (0.5 - ans)
return
321 qans = erfc1(0,sqrt(x))
ans = 0.5 + (0.5 - qans)
return
!
330 if (abs(s) .le. 2.0*e) go to 400
331 if (x .le. a) go to 300
go to 310
!
!                     Error return
!
400 ans = 2.0
return
end subroutine gratio

real function rcomp (a, x)
implicit none
real, intent(in) :: a, x
real :: rt2pin, t, t1, u
real :: exparg
real :: rlog
real :: gam1
!-----------------------------------------------------------------------
!                Evaluation of exp(-x)*x**a/gamma(a)
!-----------------------------------------------------------------------
!     rt2pin = 1/sqrt(2*pi)
!------------------------
data rt2pin/.398942280401433/
!------------------------
rcomp = 0.0
if (x .eq. 0.0) return
if (a .ge. 20.0) go to 20
!
t = a*alog(x) - x
if (t .lt. exparg(1)) return
if (a .ge. 1.0) go to 10
rcomp = (a*exp(t))*(1.0 + gam1(a))
return
10 rcomp = exp(t)/gamma(a)
return
!
20 u = x/a
if (u .eq. 0.0) return
t = (1.0/a)**2
t1 = (((0.75*t - 1.0)*t + 3.5)*t - 105.0)/(a*1260.0)
t1 = t1 - a*rlog(u)
if (t1 .ge. exparg(1)) rcomp = rt2pin*sqrt(a)*exp(t1)
return
end function rcomp

double precision function drcomp (a, x)
implicit none
!-----------------------------------------------------------------------
!              Evaluation of exp(-x)*x**a/gamma(a)
!-----------------------------------------------------------------------
double precision, intent(in) :: a, x
double precision :: c, t, w
double precision :: dgamma, dgam1, dpdel, drlog, dxparg
!--------------------------
!     c = 1/sqrt(2*pi)
!--------------------------
data c /.398942280401432677939946059934d0/
!--------------------------
drcomp = 0.d0
if (x .eq. 0.d0) return
if (a .gt. 20.d0) go to 20
!
t = a*dlog(x) - x
if (t .lt. dxparg(1)) return
if (a .ge. 1.d0) go to 10
drcomp = (a*dexp(t))*(1.d0 + dgam1(a))
return
10 drcomp = dexp(t)/dgamma(a)
return
!
20 t = x/a
if (t .eq. 0.d0) return
w = -(dpdel(a) + a*drlog(t))
if (w .ge. dxparg(1)) drcomp = c * dsqrt(a) * dexp(w)
return
end function drcomp

subroutine gaminv (a, x, x0, p, q, ierr)
implicit none
integer, intent(inout) :: ierr
real, intent(in) :: a, p, q
real, intent(out) :: x
real, intent(in) :: x0
integer :: ier, iop
real :: am1, amax, amin, ap1, ap2, ap3, apn, b, c, c1, c2, c3, c4, &
   & c5, d, e, e2, eps, g, h, pn, qg, qn, r, rta, s, s2, sum, t, tol, &
   & u, w, xmin, xn, y, z
real :: gamln1
real :: rcomp
real :: spmpar
real :: alnrel
real :: gamln
real :: ln10, bmin(2), emin(2)
!-----------------------------------------------------------------------
!
!             Inverse incomplete gamma ratio function
!
!     Given positive A, and NONEGATIVE p and q where p + q = 1.
!     Then x is computed where p(a,x) = p and q(a,x) = q. Schroder
!     iteration is employed. The routine attempts to compute x
!     to 10 significant digits if this is possible for the
!     particular computer arithmetic being used.
!
!                        ------------
!
!     x is a variable. If p = 0 Then x is assigned the value 0,
!     and if q = 0 Then x is set to the largest floating point
!     number available. Otherwise, gaminv attempts to obtain
!     a solution for p(a,x) = p and q(a,x) = q. if the routine
!     is successful then the solution is stored in x.
!
!     x0 is an optional initial approximation for x. if the user
!     does not wish to supply an initial approximation, then set
!     x0 .LE. 0.
!
!     ierr is a variable that reports the status of the results.
!     When the routine terminates, ierr has one of the following
!     values ...
!
!       ierr =  0    The solution was obtained. Iteration was
!                    not used.
!       ierr.GT.0    the solution was obtained. ierr iterations
!                    were performed.
!       ierr = -2    (INPUT ERROR) a .LE. 0
!       ierr = -3    No solution was obtained. The ratio q/a
!                    is too large.
!       ierr = -4    (INPUT ERROR) p OR q IS NEGATIVE, OR
!                    p + q .NE. 1.
!       ierr = -6    20 iterations were performed. The most
!                    recent value obtained for x is given.
!                    This cannot occur if x0 .LE. 0.
!       ierr = -7    Iteration failed. No value is given for x.
!                    This may occur when x is approximately 0.
!       ierr = -8    A value for x has been obtained, but the
!                    routine is not certain of its accuracy.
!                    Iteration cannot be performed in this
!                    case. If x0 .LE. 0, this can occur only
!                    when p or q is approximately 0. If x0 is
!                    positive then this can occur when A is
!                    exceedingly close to x and A is extremely
!                    LARGE (SAY a .GE. 1.E20).
!
!-----------------------------------------------------------------------
!     Written by Alfred H. Morris, Jr.
!        Naval Surface Warfare Center
!        Dahlgren, Virginia
!     revised ... January 1992
!------------------------
!------------------------
!     ln10 = ln(10)
!     c = Euler constant
!------------------------
data ln10 /2.302585/
data c  /.577215664901533/
!------------------------
data bmin(1) /1.e-28/, bmin(2) /1.e-13/
data emin(1) /2.e-03/, emin(2) /6.e-03/
!------------------------
data tol /1.e-5/
!------------------------
!
!     ****** E and xmin are machine dependent constants. E is the
!            smallest number for which 1.0 + E .GT. 1.0, and xmin
!            is the smallest positive number.
!
e = spmpar(1)
xmin = spmpar(2)
!
!------------------------
x = 0.0
if (a .le. 0.0) go to 500
if (p .lt. 0.0 .or. q .lt. 0.0) go to 520
t = ((p + q) - 0.5) - 0.5
if (abs(t) .gt. 5.0*amax1(e,1.e-15)) go to 520
!
ierr = 0
xmin = xmin/e
if ((p/e) .le. xmin) go to 400
if ((q/e) .le. xmin) go to 560
if (a .eq. 1.0) go to 410
!
e2 = e + e
amax = 0.4e-10/(e*e)
eps = amax1(100.0*e,1.e-10)
iop = 1
if (e .gt. 1.e-10) iop = 2
xn = x0
if (x0 .gt. 0.0) go to 100
!
!        Selection of the initial approximation XN of x
!                       WHEN a .LT. 1
!
if (a .gt. 1.0) go to 50
g = gamma(a + 1.0)
qg = q*g
if (qg .eq. 0.0) go to 560
b = qg/a
if (qg .gt. 0.6*a) go to 20
if (a .ge. 0.30 .or. b .lt. 0.35) go to 10
t = exp(-(b + c))
u = t*exp(t)
xn = t*exp(u)
go to 100
!
10 if (b .ge. 0.45) go to 20
if (b .eq. 0.0) go to 560
y = -alog(b)
s = 0.5 + (0.5 - a)
z = alog(y)
t = y - s*z
if (b .lt. 0.15) go to 11
xn = y - s*alog(t) - alog(1.0 + s/(t + 1.0))
go to 200
11 if (b .le. 1.e-2) go to 12
u = ((t + 2.0*(3.0 - a))*t + (2.0 - a)*(3.0 - a))/ &
   & ((t + (5.0 - a))*t + 2.0)
xn = y - s*alog(t) - alog(u)
go to 200
12 c1 = -s*z
c2 = -s*(1.0 + c1)
c3 = s*((0.5*c1 + (2.0 - a))*c1 + (2.5 - 1.5*a))
c4 = -s*(((c1/3.0 + (2.5 - 1.5*a))*c1 + ((a - 6.0)*a + 7.0))*c1 &
   & + ((11.0*a - 46.0)*a + 47.0)/6.0)
c5 = -s*((((-c1/4.0 + (11.0*a - 17.0)/6.0)*c1 &
   & + ((-3.0*a + 13.0)*a - 13.0))*c1 &
   & + 0.5*(((2.0*a - 25.0)*a + 72.0)*a - 61.0))*c1 &
   & + (((25.0*a - 195.0)*a + 477.0)*a - 379.0)/12.0)
xn = ((((c5/y + c4)/y + c3)/y + c2)/y + c1) + y
if (a .gt. 1.0) go to 200
if (b .gt. bmin(iop)) go to 200
x = xn
return
!
20 if (b*q .gt. 1.e-8) go to 21
xn = exp(-(q/a + c))
go to 30
21 if (p .le. 0.9) go to 22
xn = exp((alnrel(-q) + gamln1(a))/a)
go to 30
22 xn = exp(alog(p*g)/a)
!
30 if (xn .eq. 0.0) go to 510
t = 0.5 + (0.5 - xn/(a + 1.0))
xn = xn/t
go to 100
!
!        Selection of the initial approximation XN of x
!                       WHEN a .GT. 1
!
50 t = p - 0.5
if (q .lt. 0.5) t = 0.5 - q
call pni (p, q, t, s, ier)
!
rta = sqrt(a)
s2 = s*s
xn = (((12.0*s2 - 243.0)*s2 - 923.0)*s2 + 1472.0)/204120.0
xn = (xn/a + s*((9.0*s2 + 256.0)*s2 - 433.0)/(38880.0*rta)) &
   & - ((3.0*s2 + 7.0)*s2 - 16.0)/810.0
xn = a + s*rta + (s2 - 1.0)/3.0 + s*(s2 - 7.0)/(36.0*rta) &
   & + xn/a
xn = amax1(xn, 0.0)
!
amin = 20.0
if (e .lt. 1.e-8) amin = 250.0
if (a .lt. amin) go to 60
x = xn
d = 0.5 + (0.5 - x/a)
if (abs(d) .le. 1.e-1) return
!
60 if (p .le. 0.5) go to 70
if (xn .lt. 3.0*a) go to 200
w = alog(q)
y = -(w + gamln(a))
d = amax1(2.0, a*(a - 1.0))
if (y .lt. ln10*d) go to 61
s = 1.0 - a
z = alog(y)
go to 12
61 t = a - 1.0
xn = y + t*alog(xn) - alnrel(-t/(xn + 1.0))
xn = y + t*alog(xn) - alnrel(-t/(xn + 1.0))
go to 200
!
70 ap1 = a + 1.0
if (xn .gt. 0.70*ap1) go to 101
w = alog(p) + gamln(ap1)
if (xn .gt. 0.15*ap1) go to 80
ap2 = a + 2.0
ap3 = a + 3.0
x = exp((w + x)/a)
x = exp((w + x - alog(1.0 + (x/ap1)*(1.0 + x/ap2)))/a)
x = exp((w + x - alog(1.0 + (x/ap1)*(1.0 + x/ap2)))/a)
x = exp((w + x - alog(1.0 + (x/ap1)*(1.0 + (x/ap2)*(1.0 &
   & + x/ap3))))/a)
xn = x
if (xn .gt. 1.e-2*ap1) go to 80
if (xn .le. emin(iop)*ap1) return
go to 101
!
80 apn = ap1
t = xn/apn
sum = 1.0 + t
81 apn = apn + 1.0
t = t*(xn/apn)
sum = sum + t
if (t .gt. 1.e-4) go to 81
t = w - alog(sum)
xn = exp((xn + t)/a)
xn = xn*(1.0 - (a*alog(xn) - xn - t)/(a - xn))
go to 101
!
!                 Schroder iteration using p
!
100 if (p .gt. 0.5) go to 200
101 if (p .le. xmin) go to 550
am1 = (a - 0.5) - 0.5
102 if (a .le. amax) go to 110
d = 0.5 + (0.5 - xn/a)
if (abs(d) .le.e2) go to 550
!
110 if (ierr .ge. 20) go to 530
ierr = ierr + 1
call gratio (a, xn, pn, qn, 0)
if (pn .eq. 0.0 .or. qn .eq. 0.0) go to 550
r = rcomp(a,xn)
if (r .lt. xmin) go to 550
t = (pn - p)/r
w = 0.5*(am1 - xn)
if (abs(t) .le. 0.1 .and. abs(w*t) .le. 0.1) go to 120
x = xn*(1.0 - t)
if (x .le. 0.0) go to 540
d = abs(t)
go to 121
!
120 h = t*(1.0 + w*t)
x = xn*(1.0 - h)
if (x .le. 0.0) go to 540
if (abs(w) .ge. 1.0 .and. abs(w)*t*t .le. eps) return
d = abs(h)
121 xn = x
if (d .gt. tol) go to 102
if (d .le. eps) return
if (abs(p - pn) .le. tol*p) return
go to 102
!
!                 Schroder iteration using q
!
200 if (q .le. xmin) go to 550
am1 = (a - 0.5) - 0.5
201 if (a .le. amax) go to 210
d = 0.5 + (0.5 - xn/a)
if (abs(d) .le.e2) go to 550
!
210 if (ierr .ge. 20) go to 530
ierr = ierr + 1
call gratio (a, xn, pn, qn, 0)
if (pn .eq. 0.0 .or. qn .eq. 0.0) go to 550
r = rcomp(a,xn)
if (r .lt. xmin) go to 550
t = (q - qn)/r
w = 0.5*(am1 - xn)
if (abs(t) .le. 0.1 .and. abs(w*t) .le. 0.1) go to 220
x = xn*(1.0 - t)
if (x .le. 0.0) go to 540
d = abs(t)
go to 221
!
220 h = t*(1.0 + w*t)
x = xn*(1.0 - h)
if (x .le. 0.0) go to 540
if (abs(w) .ge. 1.0 .and. abs(w)*t*t .le. eps) return
d = abs(h)
221 xn = x
if (d .gt. tol) go to 201
if (d .le. eps) return
if (abs(q - qn) .le. tol*q) return
go to 201
!
!                       Special cases
!
400 ierr = -8
return
!
410 if (q .lt. 0.9) go to 411
x = -alnrel(-p)
return
411 x = -alog(q)
return
!
!                       Error return
!
500 ierr = -2
return
!
510 ierr = -3
return
!
520 ierr = -4
return
!
530 ierr = -6
return
!
540 ierr = -7
return
!
550 x = xn
ierr = -8
return
!
560 x = spmpar(3)
ierr = -8
return
end subroutine gaminv

subroutine dgrat (a, x, ans, qans, ierr)
implicit none
integer, intent(inout) :: ierr
double precision, intent(in) :: a, x
double precision, intent(inout) :: ans, qans
integer :: i, m, max, n
double precision :: amn, alog10, apn, a2n, a2nm1, big, b2n, b2nm1, &
   & c, e, g, h, j, l, r, rta, rtpi, rtx, s, sum, t, tol, twoa, u, x0, &
   & y, z, wk(20)
double precision :: dpmpar, drlog, drexp
double precision :: derf, derfc1, dgam1, drcomp
!-----------------------------------------------------------------------
!
!        Evaluation of the incomplete gamma ratio functions
!                      P(a,x) AND Q(a,x)
!
!-----------------------------------------------------------------------
!     Written by Alfred H. Morris, Jr.
!        Naval Surface Warfare Center
!        Dahlgren, Virginia
!     revised ... jan 1992
!-------------------------
!-------------------------
!     alog10 = ln(10)
!     rtpi   = dsqrt(pi)
!-------------------------
data alog10 /2.30258509299404568401799145468d0/
data rtpi   /1.77245385090551602729816748334d0/
!-------------------------
!
!     ****** E is a machine dependent constant. E is the smallest
!            floating point number for which 1.0 + E .GT. 1.0 .
!
e = dpmpar(1)
!
!-------------------------
if (a .lt. 0.d0 .or. x .lt. 0.d0) go to 400
if (a .eq. 0.d0 .and. x .eq. 0.d0) go to 410
ierr = 0
if (a*x .eq. 0.d0) go to 331
!
e = dmax1(e,1.d-30)
big = 30.d0
if (e .lt. 1.d-17) big = 50.d0
x0 = 45.d0
if (e .lt. 1.d-17) x0 = 68.d0
!
!            Select the appropriate algorithm
!
if (a .ge. 1.d0) go to 10
if (a .eq. 0.5d0) go to 320
if (x .le. 2.d0) go to 110
r = drcomp(a,x)
if (r .eq. 0.d0) go to 310
go to 170
!
10 if (a .ge. big) go to 20
if (a .gt. x .or. x .ge. x0) go to 30
twoa = a + a
m = twoa
l = m
if (twoa .ne. l) go to 30
i = m/2
l = i
if (a .eq. l) go to 140
go to 150
!
20 l = x/a
if (l .eq. 0.d0) go to 300
s = 0.5d0 + (0.5d0 - l)
z = drlog(l)
if (z .ge. 700.d0/a) go to 330
y = a*z
rta = dsqrt(a)
if (dabs(s) .le. 0.4d0) go to 200
!
30 r = drcomp(a,x)
if (r .eq. 0.d0) go to 331
if (x .le. dmax1(a,alog10)) go to 50
if (x .lt. x0) go to 170
go to 80
!
!                 Taylor series for P/R
!
50 apn = a + 1.d0
t = x/apn
wk(1) = t
do n = 2,20
   apn = apn + 1.d0
   t = t*(x/apn)
   if (t .lt. 1.d-3) go to 60
   wk(n) = t
end do
n = 20
!
60 sum = t
tol = 0.5d0*e
61 apn = apn + 1.d0
t = t*(x/apn)
sum = sum + t
if (t .gt. tol) go to 61
!
max = n - 1
do m = 1,max
   n = n - 1
   sum = sum + wk(n)
end do
ans = (r/a)*(1.d0 + sum)
qans = 0.5d0 + (0.5d0 - ans)
return
!
!                 Asymptotic expansion
!
80 amn = a - 1.d0
t = amn/x
wk(1) = t
do n = 2,20
   amn = amn - 1.d0
   t = t*(amn/x)
   if (dabs(t) .le. 1.d-3) go to 90
   wk(n) = t
end do
n = 20
!
90 sum = t
91 if (dabs(t) .lt. e) go to 100
amn = amn - 1.d0
t = t*(amn/x)
sum = sum + t
go to 91
!
100 max = n - 1
do m = 1,max
   n = n - 1
   sum = sum + wk(n)
end do
qans = (r/x)*(1.d0 + sum)
ans = 0.5d0 + (0.5d0 - qans)
return
!
!             Taylor series for P(a,x)/x**a
!
110 l = 3.d0
c = x
sum = x/(a + 3.d0)
tol = 3.d0*e/(a + 1.d0)
120 l = l + 1.d0
c = -c*(x/l)
t = c/(a + l)
sum = sum + t
if (dabs(t) .gt. tol) go to 120
j = a*x*((sum/6.d0 - 0.5d0/(a + 2.d0))*x + 1.d0/(a + 1.d0))
!
z = a*dlog(x)
u = dexp(z)
h = dgam1(a)
g = 1.d0 + h
ans = u*g*(0.5d0 + (0.5d0 - j))
qans = 0.5d0 + (0.5d0 - ans)
if (ans .le. 0.9d0) return
!
l = drexp(z)
qans = (u*j - l)*g - h
if (qans .le. 0.d0) go to 310
ans = 0.5d0 + (0.5d0 - qans)
return
!
!             Finite sums for Q when a .GE. 1
!                 and 2*a is an integer
!
140 sum = dexp(-x)
t = sum
n = 1
c = 0.d0
go to 160
!
150 rtx = dsqrt(x)
sum = derfc1(0,rtx)
t = dexp(-x)/(rtpi*rtx)
n = 0
c = -0.5d0
!
160 if (n .eq. i) go to 161
n = n + 1
c = c + 1.d0
t = (x*t)/c
sum = sum + t
go to 160
161 qans = sum
ans = 0.5d0 + (0.5d0 - qans)
return
!
!              Continued fraction expansion
!
170 tol = 8.d0*e
a2nm1 = 1.d0
a2n = 1.d0
b2nm1 = x
b2n = x + (1.d0 - a)
c = 1.d0
180 a2nm1 = x*a2n + c*a2nm1
b2nm1 = x*b2n + c*b2nm1
c = c + 1.d0
t = c - a
a2n = a2nm1 + t*a2n
b2n = b2nm1 + t*b2n
!
a2nm1 = a2nm1/b2n
b2nm1 = b2nm1/b2n
a2n = a2n/b2n
b2n = 1.d0
if (dabs(a2n - a2nm1/b2nm1) .ge. tol*a2n) go to 180
!
qans = r*a2n
ans = 0.5d0 + (0.5d0 - qans)
return
!
!                 Minimax approximations
!
200 if (dabs(s) .le. 2.d0*e .and. a*e*e .gt. 3.28d-3) go to 420
if (e .lt. 1.d-17) go to 210
call dgr17 (a, y, l, z, rta, ans, qans)
return
210 call dgr29 (a, y, l, z, rta, ans, qans)
return
!
!                     Special cases
!
300 ans = 0.d0
qans = 1.d0
return
!
310 ans = 1.d0
qans = 0.d0
return
!
320 if (x .ge. 0.25d0) go to 321
ans = derf(dsqrt(x))
qans = 0.5d0 + (0.5d0 - ans)
return
321 qans = derfc1(0,dsqrt(x))
ans = 0.5d0 + (0.5d0 - qans)
return
!
330 if (dabs(s) .le. 2.d0*e) go to 420
331 if (x .le. a) go to 300
go to 310
!
!                     Error return
!
400 ierr = 1
ans = 2.d0
return
!
410 ierr = 2
ans = 2.d0
return
!
420 ierr = 3
ans = 2.d0
return
end subroutine dgrat

