   & w(173)/.29799232151870e+03/, w(174)/.30022094864701e+03/, &
   & w(175)/.30245246593264e+03/, w(176)/.30468685676567e+03/, &
   & w(177)/.30692410472600e+03/, w(178)/.30916419358015e+03/, &
   & w(179)/.31140710727802e+03/, w(180)/.31365282994988e+03/
data w(181)/.31590134590330e+03/, w(182)/.31815263962021e+03/, &
   & w(183)/.32040669575401e+03/, w(184)/.32266349912673e+03/, &
   & w(185)/.32492303472629e+03/, w(186)/.32718528770378e+03/, &
   & w(187)/.32945024337081e+03/, w(188)/.33171788719693e+03/, &
   & w(189)/.33398820480710e+03/, w(190)/.33626118197920e+03/, &
   & w(191)/.33853680464160e+03/, w(192)/.34081505887080e+03/, &
   & w(193)/.34309593088909e+03/, w(194)/.34537940706227e+03/, &
   & w(195)/.34766547389743e+03/, w(196)/.34995411804077e+03/, &
   & w(197)/.35224532627544e+03/, w(198)/.35453908551944e+03/, &
   & w(199)/.35683538282361e+03/, w(200)/.35913420536958e+03/
!     ------------------------------------------------------------------
if (x .gt. 100.0) go to 10
n = 2.0*x + 0.1
logam = w(n)
return
10 t = (1.0/x)**2
z = (((-0.75*t + 1.0)*t - 3.5)*t + 105.0)/(x*1260.0)
logam = (d + z) + (x - 0.5)*(alog(x) - 1.0)
return
end function logam

subroutine cbsslj (z, cnu, w)
implicit none
complex :: z
complex, intent(in) :: cnu
complex, intent(inout) :: w
integer :: i, k, m, n
real :: a, cn1, cn2, e, fn, pi, pn, qm, qn, qnp1, r, r2, rn2, sn, &
   & t1, t2, u, v, x, y
complex :: c, nu, s, sm1, sm2, t, tsc, w0, w1, zn, zz
complex :: cgam0
interface
   pure elemental function cdiv(a,b)
      implicit none
      complex, intent(in) :: a
      complex, intent(in) :: b
      complex :: cdiv
   end function cdiv
   pure elemental function cpabs(x,y)
      implicit none
      real, intent(in) :: x
      real, intent(in) :: y
      real :: cpabs
   end function cpabs
end interface
!-----------------------------------------------------------------------
!
!         EVALUATION OF THE COMPLEX BESSEL FUNCTION J   (z)
!                                                    cnu
!-----------------------------------------------------------------------
!
!     Written by
!         Andrew H. van Tuyl and Alfred H. Morris, Jr.
!         Naval Surface Warfare Center
!         October, 1991
!
!     A modification of the procedure developed by allen V. hershey
!     (Naval Surface Warfare Center) in 1978 for handling the debye
!     approximation is employed.
!
!-----------------------------------------------------------------------
!-----------------------
data pi /3.14159265358979/
!-----------------------
x = real(z)
y = aimag(z)
r = cpabs(x,y)
cn1 = real(cnu)
cn2 = aimag(cnu)
rn2 = cn1*cn1 + cn2*cn2
pn = aint(cn1)
fn = cn1 - pn
!
!          Calculation when order is an integer
!
sn = 1.0
if (fn .ne. 0.0 .or. cn2 .ne. 0.0) go to 10
n = pn
pn = abs(pn)
cn1 = pn
if (n .lt. 0 .and. n .ne. (n/2)*2) sn = -1.0
!
!          Selection of method
!
10 if (r .le. 17.5) go to 20
if (r .gt. 17.5 + 0.5*rn2) go to 40
go to 50
!
!          Use Maclaurin expansion and recursion
!
20 if (cn1 .ge. 0.0) go to 30
qn = -1.25*(r + 0.5*abs(cn2) - abs(y - 0.5*cn2))
if (cn1 .ge. qn) go to 30
qn = 1.25*(r - amax1(1.2*r,abs(y - cn2)))
if (cn1 .ge. qn) go to 30
qn = amin1(pn, -aint(1.25*(r - abs(cn2))))
go to 130
!
30 r2 = r*r
qm = 0.0625*r2*r2 - cn2*cn2
qn = amax1(pn, aint(sqrt(0.5*(qm + abs(qm)))))
go to 130
!
!          Use asymptotic expansion
!
40 call cbja(z, cnu, w)
return
!
!          Calculation for 17.5 .LT. abs(z) .LE. 17.5 + 0.5*abs(cnu)**2
!
50 n = 0
if (abs(cn2) .ge. 0.8*abs(y)) go to 60
qm = -1.25*(r + 0.5*abs(cn2) - abs(y - 0.5*cn2))
if (cn1 .ge. qm) go to 60
qm = 1.25*(r - amax1(1.2*r,abs(y - cn2)))
if (cn1 .lt. qm) n = 1
!
60 qn = pn
a = 4.e-3*r*r
zz = z
if (x .lt. 0.0) zz = -z
!
!          Calculation of zone of exclusion of debye approximation
!
70 nu = cmplx(qn + fn, cn2)
zn = nu/z
t2 = aimag(zn)*aimag(zn)
u = 1.0 - real(zn)
t1 = u*u + t2
u = 1.0 + real(zn)
t2 = u*u + t2
u = t1*t2
v = a*u/(t1*t1 + t2*t2)
if (u*v*v .gt. 1.0) go to 80
!
!          The argument lies inside the zone of exclusion
!
qn = qn + 1.0
if (n .eq. 0) go to 70
!
!          Use Maclaurin expansion with forward recurrence
!
qn = amin1(pn, -aint(1.25*(r - abs(cn2))))
go to 130
!
!          Use backward recurrence starting from the
!          asymptotic expansion
!
80 qnp1 = qn + 1.0
if (abs(qn) .ge. abs(pn)) go to 100
if (r .lt. 17.5 + 0.5*(qnp1*qnp1 + cn2*cn2)) go to 100
!
nu = cmplx(qn + fn, cn2)
call cbja (zz, nu, sm1)
nu = cmplx(qnp1 + fn, cn2)
call cbja (zz, nu, sm2)
go to 110
!
!          Use backward recurrence starting from the
!          debye approximation
!
100 nu = cmplx(qn + fn, cn2)
call cbdb (zz, nu, fn, sm1)
if (qn .eq. pn) go to 120
nu = cmplx(qnp1 + fn, cn2)
call cbdb (zz, nu, fn, sm2)
!
110 nu = cmplx(qn + fn, cn2)
tsc = 2.0*nu*sm1/zz - sm2
sm2 = sm1
sm1 = tsc
qn = qn - 1.0
if (qn .ne. pn) go to 110
!
120 w = sm1
if (sn .lt. 0.0) w = -w
if (x .ge. 0.0) return
!
nu = pi*cmplx(-cn2, cn1)
if (y .lt. 0.0) nu = -nu
w = cexp(nu)*w
return
!
!          Use Maclaurin expansion with forward or backward recurrence.
!
130 m = qn - pn
if (iabs(m) .gt. 1) go to 140
nu = cmplx(cn1, cn2)
call cbjm (z, nu, w)
go to 180
140 nu = cmplx(qn + fn, cn2)
call cbjm (z, nu, w1)
w0 = 0.25*z*z
if (m .gt. 0) go to 160
!
!          Forward recurrence
!
m = iabs(m)
nu = nu + 1.0
call cbjm (z, nu, w)
do i = 2,m
   c = nu*(nu + 1.0)
   t = (c/w0)*(w - w1)
   w1 = w
   w = t
   nu = nu + 1.0
end do
go to 180
!
!          Backward recurrence
!
160 nu = nu - 1.0
call cbjm (z, nu, w)
do i = 2,m
   c = nu*(nu + 1.0)
   t = (w0/c)*w1
   w1 = w
   w = w - t
   nu = nu - 1.0
end do
!
!          Final assembly
!
180 if (fn .ne. 0.0 .or. cn2 .ne. 0.0) go to 190
k = pn
if (k .eq. 0.0) return
e = sn/gamma(pn + 1.0)
w = e*w*(0.5*z)**k
return
!
190 s = cnu*clog(0.5*z)
w = cexp(s)*w
if (rn2 .gt. 0.81) go to 200
w = w*cgam0(cnu)
return
200 call cgamma(0, cnu, t)
w = cdiv(w, cnu*t)
return
end subroutine cbsslj

subroutine cbjm (z, cnu, w)
implicit none
complex, intent(in) :: cnu
complex, intent(inout) :: w
complex :: z
integer :: i, imin, k, km1, km2
real :: a, a0, eps, rnu
real :: anorm
real :: spmpar
complex :: nu, nup1, p, s, sn, t, ti
real :: inu, m
interface
   pure elemental function cdiv(a,b)
      implicit none
      complex, intent(in) :: a
      complex, intent(in) :: b
      complex :: cdiv
   end function cdiv
end interface
!-----------------------------------------------------------------------
!
!       COMPUTATION OF  (z/2)**(-cnu) * gamma(cnu + 1) * J(cnu,z)
!
!                           -----------------
!
!     The Maclaurin expansion is used. It is assumed that cnu is not
!     a negative integer.
!
!-----------------------------------------------------------------------
!--------------------------
anorm(z) = amax1(abs(real(z)),abs(aimag(z)))
!--------------------------
!
!     ****** eps is a machine dependent constant. Eps is the
!            smallest number such that 1.0 + eps .GT. 1.0 .
!
eps = spmpar(1)
!
!--------------------------
s = -0.25*(z*z)
nu = cnu
rnu = real(nu)
inu = aimag(nu)
a = 0.5 + (0.5 + rnu)
nup1 = cmplx(a, inu)
!
if (a .le. 0.0) go to 10
m = 1.0
t = s/nup1
w = 1.0 + t
go to 70
!
!     Add 1.0 and the first k-1 terms
!
10 k = int(-a) + 2
km1 = k - 1
w = (1.0, 0.0)
t = w
do i = 1,km1
   m = i
   t = t*(s/(m*(nu + m)))
   w = w + t
   if (anorm(t) .le. eps*anorm(w)) go to 30
end do
go to 70
!
!     Check if the (k-1)-ST and k-TH terms can be ignored.
!     If so then the summation is complete.
!
30 if (i .eq. km1) go to 70
imin = i + 1
if (imin .ge. k - 5) go to 50
ti = t
!
m = km1
t = s/(nu + m)
a0 = anorm(t)/m
t = t * (s/(nu + (m + 1.0)))
a = anorm(t)/(m*(m + 1.0))
a = amax1(a, a0)
!
t = (1.0, 0.0)
km2 = k - 2
do i = imin,km2
   m = i
   t = t*(s/(m*(nu + m)))
   if (a*anorm(t) .lt. 0.5) return
end do
t = t*ti
imin = km2
!
!     Add the (k-1)-ST term
!
50 a = 1.0
p = (1.0, 0.0)
sn = p
do i = imin,km1
   m = i
   a = a*m
   p = p*(nu + m)
   sn = s*sn
end do
t = t*(cdiv(sn,p)/a)
w = w + t
!
!     Add the remaining terms
!
70 m = m + 1.0
t = t*(s/(m*(nu + m)))
w = w + t
if (anorm(t) .gt. eps*anorm(w)) go to 70
!
return
end subroutine cbjm

subroutine cbdb (cz, cnu, fn, w)
implicit none
real, intent(in) :: fn
complex, intent(in) :: cz, cnu
complex, intent(inout) :: w
integer :: ind, k, l, m
real :: alpha, am, aq, ar, bnd, c, phi, pi, pi2, sgn, theta, u, v, &
   & x, y
real :: a(136), is, inu, izn
complex :: c1, c2, eta, j, nu, p, p1, q, r, s, s1, s2, sm, t, z, &
   & zn
interface
   pure elemental subroutine crec(x,y,u,v)
      implicit none
      real, intent(in) :: x
      real, intent(in) :: y
      real, intent(inout) :: u
      real, intent(inout) :: v
   end subroutine crec
end interface
!-----------------------------------------------------------------------
!
!         CALCULATION OF j   (cz) BY THE DEBYE APPROXIMATION
!                         cnu
!                         ------------------
!
!     It is assumed that real(cz) .GE. 0 and that real(cnu) = fn + k
!     where k is an integer.
!
!-----------------------------------------------------------------------
!----------------------
!     c = 1/sqrt(2)
!     bnd = pi/3
!----------------------
data j   /(0.0, 1.0)/
data c   /.398942280401433/
data pi  /3.14159265358979/
data pi2 /6.28318530717959/
data bnd /1.04719755119660/
!----------------------
!
!             Coefficients of the first 16 polynomials
!                   in the debye approximation
!
!
data a(1)  /1.0/
data a(2)  /-.208333333333333e+00/, a(3)  / .125000000000000e+00/
data a(4)  / .334201388888889e+00/, a(5)  /-.401041666666667e+00/, &
   & a(6)  / .703125000000000e-01/
data a(7)  /-.102581259645062e+01/, a(8)  / .184646267361111e+01/, &
   & a(9)  /-.891210937500000e+00/, a(10) / .732421875000000e-01/
data a(11) / .466958442342625e+01/, a(12) /-.112070026162230e+02/, &
   & a(13) / .878912353515625e+01/, a(14) /-.236408691406250e+01/, &
   & a(15) / .112152099609375e+00/
data a(16) /-.282120725582002e+02/, a(17) / .846362176746007e+02/, &
   & a(18) /-.918182415432400e+02/, a(19) / .425349987453885e+02/, &
   & a(20) /-.736879435947963e+01/, a(21) / .227108001708984e+00/
data a(22) / .212570130039217e+03/, a(23) /-.765252468141182e+03/, &
   & a(24) / .105999045252800e+04/, a(25) /-.699579627376133e+03/, &
   & a(26) / .218190511744212e+03/, a(27) /-.264914304869516e+02/, &
   & a(28) / .572501420974731e+00/
data a(29) /-.191945766231841e+04/, a(30) / .806172218173731e+04/, &
   & a(31) /-.135865500064341e+05/, a(32) / .116553933368645e+05/, &
   & a(33) /-.530564697861340e+04/, a(34) / .120090291321635e+04/, &
   & a(35) /-.108090919788395e+03/, a(36) / .172772750258446e+01/
data a(37) / .202042913309661e+05/, a(38) /-.969805983886375e+05/, &
   & a(39) / .192547001232532e+06/, a(40) /-.203400177280416e+06/, &
   & a(41) / .122200464983017e+06/, a(42) /-.411926549688976e+05/, &
   & a(43) / .710951430248936e+04/, a(44) /-.493915304773088e+03/, &
   & a(45) / .607404200127348e+01/
data a(46) /-.242919187900551e+06/, a(47) / .131176361466298e+07/, &
   & a(48) /-.299801591853811e+07/, a(49) / .376327129765640e+07/, &
   & a(50) /-.281356322658653e+07/, a(51) / .126836527332162e+07/, &
   & a(52) /-.331645172484564e+06/, a(53) / .452187689813627e+05/, &
   & a(54) /-.249983048181121e+04/, a(55) / .243805296995561e+02/
data a(56) / .328446985307204e+07/, a(57) /-.197068191184322e+08/, &
   & a(58) / .509526024926646e+08/, a(59) /-.741051482115327e+08/, &
   & a(60) / .663445122747290e+08/, a(61) /-.375671766607634e+08/, &
   & a(62) / .132887671664218e+08/, a(63) /-.278561812808645e+07/, &
   & a(64) / .308186404612662e+06/, a(65) /-.138860897537170e+05/, &
   & a(66) / .110017140269247e+03/
data a(67) /-.493292536645100e+08/, a(68) / .325573074185766e+09/, &
   & a(69) /-.939462359681578e+09/, a(70) / .155359689957058e+10/, &
   & a(71) /-.162108055210834e+10/, a(72) / .110684281682301e+10/, &
   & a(73) /-.495889784275030e+09/, a(74) / .142062907797533e+09/, &
   & a(75) /-.244740627257387e+08/, a(76) / .224376817792245e+07/, &
   & a(77) /-.840054336030241e+05/, a(78) / .551335896122021e+03/
data a(79) / .814789096118312e+09/, a(80) /-.586648149205185e+10/, &
   & a(81) / .186882075092958e+11/, a(82) /-.346320433881588e+11/, &
   & a(83) / .412801855797540e+11/, a(84) /-.330265997498007e+11/, &
   & a(85) / .179542137311556e+11/, a(86) /-.656329379261928e+10/, &
   & a(87) / .155927986487926e+10/, a(88) /-.225105661889415e+09/, &
   & a(89) / .173951075539782e+08/, a(90) /-.549842327572289e+06/, &
   & a(91) / .303809051092238e+04/
data a(92) /-.146792612476956e+11/, a(93) / .114498237732026e+12/, &
   & a(94) /-.399096175224466e+12/, a(95) / .819218669548577e+12/, &
   & a(96) /-.109837515608122e+13/, a(97) / .100815810686538e+13/, &
   & a(98) /-.645364869245377e+12/, a(99) / .287900649906151e+12/, &
   & a(100)/-.878670721780233e+11/, a(101)/ .176347306068350e+11/, &
   & a(102)/-.216716498322380e+10/, a(103)/ .143157876718889e+09/, &
   & a(104)/-.387183344257261e+07/, a(105)/ .182577554742932e+05/
data a(106)/ .286464035717679e+12/, a(107)/-.240629790002850e+13/, &
   & a(108)/ .910934118523990e+13/, a(109)/-.205168994109344e+14/, &
   & a(110)/ .305651255199353e+14/, a(111)/-.316670885847852e+14/, &
   & a(112)/ .233483640445818e+14/, a(113)/-.123204913055983e+14/, &
   & a(114)/ .461272578084913e+13/, a(115)/-.119655288019618e+13/, &
   & a(116)/ .205914503232410e+12/, a(117)/-.218229277575292e+11/, &
   & a(118)/ .124700929351271e+10/, a(119)/-.291883881222208e+08/, &
   & a(120)/ .118838426256783e+06/
data a(121)/-.601972341723401e+13/, a(122)/ .541775107551060e+14/, &
   & a(123)/-.221349638702525e+15/, a(124)/ .542739664987660e+15/, &
   & a(125)/-.889496939881026e+15/, a(126)/ .102695519608276e+16/, &
   & a(127)/-.857461032982895e+15/, a(128)/ .523054882578445e+15/, &
   & a(129)/-.232604831188940e+15/, a(130)/ .743731229086791e+14/, &
   & a(131)/-.166348247248925e+14/, a(132)/ .248500092803409e+13/, &
   & a(133)/-.229619372968246e+12/, a(134)/ .114657548994482e+11/, &
   & a(135)/-.234557963522252e+09/, a(136)/ .832859304016289e+06/
!----------------------
z = cz
nu = cnu
inu = aimag(cnu)
if (inu .ge. 0.0) go to 10
z = conjg(z)
nu = conjg(nu)
10 x = real(z)
y = aimag(z)
!
!          tanh(gamma) = sqrt(1 - (z/nu)**2) = w/nu
!          t = exp(nu*(tanh(gamma) - gamma))
!
zn = z/nu
izn = aimag(zn)
if (abs(izn) .gt. 0.1*abs(real(zn))) go to 20
!
s = (1.0 - zn)*(1.0 + zn)
eta = 1.0/s
q = csqrt(s)
s = 1.0/(nu*q)
t = zn/(1.0 + q)
t = cexp(nu*(q + clog(t)))
go to 30

20 s = (nu - z)*(nu + z)
eta = (nu*nu)/s
w = csqrt(s)
q = w/nu
if (real(q) .lt. 0.0) w = -w
s = 1.0/w
t = z/(nu + w)
t = cexp(w + nu*clog(t))
!
30 is = aimag(s)
r = csqrt(s)
c1 = r*t
ar = real(r)*real(r) + aimag(r)*aimag(r)
aq = -1.0/(real(q)*real(q) + aimag(q)*aimag(q))
!
phi = atan2(y,x)/3.0
q = nu - z
theta = atan2(aimag(q),real(q)) - phi
ind = 0
if (abs(theta) .lt. 2.0*bnd) go to 50
!
ind = 1
call crec(real(t), aimag(t), u, v)
c2 = -j*r*cmplx(u, v)
if (is .lt. 0.0) go to 40
if (is .gt. 0.0) go to 50
if (real(s) .le. 0.0) go to 50
40 c2 = -c2
!
!          Summation of the series s1 and s2
!
50 sm = s*s
p = (a(2)*eta + a(3))*s
p1 = ((a(4)*eta + a(5))*eta + a(6))*sm
s1 = (1.0 + p) + p1
if (ind .ne. 0) s2 = (1.0 - p) + p1
sgn = 1.0
am = ar*ar
m = 4
l = 6
!
!          p = Value of the m-TH polynomial
!
60 l = l + 1
alpha = a(l)
p = cmplx(a(l),0.0)
do 70 k = 2,m
   l = l + 1
   alpha = a(l) + aq*alpha
   p = a(l) + eta*p
70 continue
!
!          Only the s1 sum is formed when ind = 0
!
sm = s*sm
p = p*sm
s1 = s1 + p
if (ind .eq. 0) go to 80
sgn = -sgn
s2 = s2 + sgn*p
80 am = ar*am
if (1.0 + alpha*am .eq. 1.0) go to 100
m = m + 1
if (m .le. 16) go to 60
!
!          Final assembly
!
100 s1 = c*c1*s1
if (ind .ne. 0) go to 110
w = s1
go to 200
!
110 s2 = c*c2*s2
q = nu + z
theta = atan2(aimag(q),real(q)) - phi
if (abs(theta) .gt. bnd) go to 120
w = s1 + s2
go to 200
!
120 alpha = pi2
if (izn .lt. 0.0) alpha = -alpha
t = alpha*cmplx(abs(inu), -fn)
alpha = exp(real(t))
u = aimag(t)
r = cmplx(cos(u),sin(u))
t = s1 - (alpha*r)*s1
if (x .eq. 0.0 .and. inu .eq. 0.0) t = -t
!
if (y .ge. 0.0) go to 170
if (izn .ge. 0.0 .and. theta .le. sign(pi,theta)) &
   & s2 = s2*(conjg(r)/alpha)
if (x .eq. 0.0) go to 180
if (izn .lt. 0.0) go to 170
if (is .lt. 0.0) go to 180
!
170 w = s2 + t
go to 200
180 w = s2 - t
!
200 if (inu .lt. 0.0) w = conjg(w)
return
end subroutine cbdb

subroutine cbja (cz, cnu, w)
implicit none
complex, intent(in) :: cz, cnu
complex, intent(inout) :: w
integer :: i, ind
real :: c, eps, pihalf, r, rnu, tol, u, v, x, y
real :: sin1
real :: cos1
real :: anorm
real :: spmpar
real :: inu, m
complex :: a, a1, arg, e, eta, j, nu, p, q, t, z, zr, zz
interface
   pure elemental subroutine crec(x,y,u,v)
      implicit none
      real, intent(in) :: x
      real, intent(in) :: y
      real, intent(inout) :: u
      real, intent(inout) :: v
   end subroutine crec
end interface
!-----------------------------------------------------------------------
!        Computation of j(nu,z) by the asymptotic expansion
!-----------------------------------------------------------------------
!--------------------------
anorm(z) = amax1(abs(real(z)), abs(aimag(z)))
!--------------------------
!     pihalf = pi/2
!     c = 2*pi**(-1/2)
!--------------------------
data pihalf /1.5707963267949/
data c /1.12837916709551/
data j /(0.0, 1.0)/
!--------------------------
!
!     ****** eps is a machine dependent constant. Eps is the
!            smallest number such that 1.0 + eps .GT. 1.0 .
!
eps = spmpar(1)
!
!--------------------------
z = cz
x = real(z)
y = aimag(z)
nu = cnu
ind = 0
if (abs(x) .gt. 1.e-2*abs(y)) go to 10
if (aimag(nu) .ge. 0.0 .or. abs(real(nu)) .ge. &
   & 1.e-2*abs(aimag(nu))) go to 10
ind = 1
nu = conjg(nu)
z = conjg(z)
y = -y
!
10 if (x .lt. -1.e-2*y) z = -z
zz = z + z
call crec (real(zz), aimag(zz), u, v)
zr = cmplx(u, v)
eta = -zr*zr
!
p = (0.0,0.0)
q = (0.0,0.0)
a1 = nu*nu - 0.25
a = a1
t = a1
m = 1.0
tol = eps*anorm(a1)
do i = 1,16
   a = a - 2.0*m
   m = m + 1.0
   t = t*a*eta/m
   p = p + t
   a = a - 2.0*m
   m = m + 1.0
   t = t*a/m
   q = q + t
   if (anorm(t) .le. tol) go to 30
end do
!
30 p = p + 1.0
q = (q + a1)*zr
w = z - pihalf*nu
if (abs(aimag(w)) .gt. 1.0) go to 40
arg = w - 0.5*pihalf
w = c*csqrt(zr)*(p*ccos(arg) - q*csin(arg))
go to 50
40 e = cexp(-j*w)
t = q - j*p
if (aimag(z) .gt. 0.0 .and. real(z) .le. 1.e-2*aimag(z) .and. &
   & abs(real(nu)) .lt. 1.e-2*aimag(nu)) t = 0.5*t
call crec(real(e), aimag(e), u, v)
w = 0.5*c*csqrt(j*zr)*((p - j*q)*e + t*cmplx(u, v))
!
50 if (x .ge. -1.e-2*y) go to 60
if (y .lt. 0.0) nu = -nu
!
!     Computation of exp(i*PI*nu)
!
rnu = real(nu)
inu = aimag(nu)
r = exp(-2.0*pihalf*inu)
u = r*cos1(rnu)
v = r*sin1(rnu)
w = w*cmplx(u,v)
!
60 if (ind .ne. 0) w = conjg(w)
return
end subroutine cbja

subroutine bsslj (a, in, w)
implicit none
integer, intent(in) :: in
complex, intent(in) :: a
complex, intent(inout) :: w
integer :: i, m, n
real :: an, aq(2), az(2), cd(30), ce(30), fj(2), pm, pn, qf(2), &
   & qm, qn, qz(2), rm(4), rz(2), sm(4), sn, ss, sz(2), tm(2), ts(2), &
   & zm, zr(2), zs
!     ******************************************************************
!     Fortran subroutine for ordinary Bessel function of integral order
!     ******************************************************************
!     a  = ARGUMENT (COMPLEX NUMBER)
!     in = order (integer)
!     w  = Function of first kind (complex number)
!     -------------------
data cd(1) / 0.00000000000000e00/,  cd(2) /-1.64899505142212e-2/, &
   & cd(3) /-7.18621880068536e-2/,  cd(4) /-1.67086878124866e-1/, &
   & cd(5) /-3.02582250219469e-1/,  cd(6) /-4.80613945245927e-1/, &
   & cd(7) /-7.07075239357898e-1/,  cd(8) /-9.92995790539516e-1/, &
   & cd(9) /-1.35583925612592e00/,  cd(10)/-1.82105907899132e00/, &
   & cd(11)/-2.42482175310879e00/,  cd(12)/-3.21956655708750e00/, &
   & cd(13)/-4.28658077248384e00/,  cd(14)/-5.77022816798128e00/, &
   & cd(15)/-8.01371260952526e00/
data cd(16)/ 0.00000000000000e00/,  cd(17)/-5.57742429879505e-3/, &
   & cd(18)/-4.99112944172476e-2/,  cd(19)/-1.37440911652397e-1/, &
   & cd(20)/-2.67233784710566e-1/,  cd(21)/-4.40380166808682e-1/, &
   & cd(22)/-6.61813614872541e-1/,  cd(23)/-9.41861077665017e-1/, &
   & cd(24)/-1.29754130468326e00/,  cd(25)/-1.75407696719816e00/, &
   & cd(26)/-2.34755299882276e00/,  cd(27)/-3.13041332689196e00/, &
   & cd(28)/-4.18397120563729e00/,  cd(29)/-5.65251799214994e00/, &
   & cd(30)/-7.87863959810677e00/
data ce(1) / 0.00000000000000e00/,  ce(2) /-4.80942336387447e-3/, &
   & ce(3) /-1.31366200347759e-2/,  ce(4) /-1.94843834008458e-2/, &
   & ce(5) /-2.19948900032003e-2/,  ce(6) /-2.09396625676519e-2/, &
   & ce(7) /-1.74600268458650e-2/,  ce(8) /-1.27937813362085e-2/, &
   & ce(9) /-8.05234421796592e-3/,  ce(10)/-4.15817375002760e-3/, &
   & ce(11)/-1.64317738747922e-3/,  ce(12)/-4.49175585314709e-4/, &
   & ce(13)/-7.28594765574007e-5/,  ce(14)/-5.38265230658285e-6/, &
   & ce(15)/-9.93779048036289e-8/
data ce(16)/ 0.00000000000000e00/,  ce(17)/ 7.53805779200591e-2/, &
   & ce(18)/ 7.12293537403464e-2/,  ce(19)/ 6.33116224228200e-2/, &
   & ce(20)/ 5.28240264523301e-2/,  ce(21)/ 4.13305359441492e-2/, &
   & ce(22)/ 3.01350573947510e-2/,  ce(23)/ 2.01043439592720e-2/, &
   & ce(24)/ 1.18552223068074e-2/,  ce(25)/ 5.86055510956010e-3/, &
   & ce(26)/ 2.25465148267325e-3/,  ce(27)/ 6.08173041536336e-4/, &
   & ce(28)/ 9.84215550625747e-5/,  ce(29)/ 7.32139093038089e-6/, &
   & ce(30)/ 1.37279667384666e-7/
!     -------------------
az(1) = real(a)
az(2) = aimag(a)
zs = az(1)*az(1) + az(2)*az(2)
zm = sqrt(zs)
pn = iabs(in)
sn = 1.0
if (in) 002,003,003
002 if (in.eq.in/2*2) go to 003
sn = -1.0
003 if (az(1)) 004,005,005
004 qz(1) = -az(1)
qz(2) = -az(2)
if (in.eq.in/2*2) go to 006
sn = -sn
go to 006
005 qz(1) = az(1)
qz(2) = az(2)
006 if (zm.le.17.5 + 0.5*pn*pn) go to 007
qn = pn
go to 013
007 qn = 0.5*zm - 0.5*abs(qz(2)) + 0.5*abs(0.5*zm - abs(qz(2)))
if (pn.le.qn) go to 008
qn = aint(0.0625*zs)
if (pn.le.qn) go to 031
qn = pn
go to 031
008 if (zm.le.17.5) go to 009
qn = aint(sqrt(2.0*(zm - 17.5)))
go to 013
009 if (zs - 1.0) 011,010,010
010 if (-abs(az(2)) + 0.096*az(1)*az(1)) 011,012,012
011 qn = aint(0.0625*zs)
if (pn.le.qn) go to 031
qn = pn
go to 031
012 qn = 0.0
013 sz(1) = qz(1)
sz(2) = qz(2)
qm = sn*0.797884560802865
zr(1) = sqrt(sz(1) + zm)
zr(2) = sz(2)/zr(1)
zr(1) = 0.707106781186548*zr(1)
zr(2) = 0.707106781186548*zr(2)
qf(1) = qm*zr(1)/zm
qf(2) = -qm*zr(2)/zm
if (zm.le.17.5) go to 018
014 rz(1) = 0.5*qz(1)/zs
rz(2) = -0.5*qz(2)/zs
an = qn*qn - 0.25
sm(1) = 0.0
sm(2) = 0.0
sm(3) = 0.0
sm(4) = 0.0
tm(1) = 1.0
tm(2) = 0.0
pm = 0.0
go to 016
015 an = an - 2.0*pm
pm = pm + 1.0
ts(1) = tm(1)*rz(1) - tm(2)*rz(2)
ts(2) = tm(1)*rz(2) + tm(2)*rz(1)
tm(1) = -an*ts(1)/pm
tm(2) = -an*ts(2)/pm
016 sm(1) = sm(1) + tm(1)
sm(2) = sm(2) + tm(2)
an = an - 2.0*pm
pm = pm + 1.0
ts(1) = tm(1)*rz(1) - tm(2)*rz(2)
ts(2) = tm(1)*rz(2) + tm(2)*rz(1)
tm(1) = an*ts(1)/pm
tm(2) = an*ts(2)/pm
if (abs(sm(3)) + abs(tm(1)).ne.abs(sm(3))) go to 017
if (abs(sm(4)) + abs(tm(2)).eq.abs(sm(4))) go to 020
017 sm(3) = sm(3) + tm(1)
sm(4) = sm(4) + tm(2)
if (pm.lt.35.0) go to 015
go to 020
018 sm(1) = 1.0
sm(2) = 0.0
sm(3) = 1.0
sm(4) = 0.0
m = 15.0*qn + 2.0
n = 15.0*qn + 15.0
do 019 i = m,n
   ts(1) = qz(2) - cd(i)
   ts(2) = -qz(1)
   ss = ts(1)*ts(1) + ts(2)*ts(2)
   tm(1) = ce(i)*ts(1)/ss
   tm(2) = -ce(i)*ts(2)/ss
   sm(1) = sm(1) + tm(1)
   sm(2) = sm(2) + tm(2)
   ts(1) = -qz(2) - cd(i)
   ts(2) = qz(1)
   ss = ts(1)*ts(1) + ts(2)*ts(2)
   tm(1) = ce(i)*ts(1)/ss
   tm(2) = -ce(i)*ts(2)/ss
   sm(3) = sm(3) + tm(1)
   sm(4) = sm(4) + tm(2)
019 continue
ts(1) = 0.5*(sm(2) - sm(4))
ts(2) = -0.5*(sm(1) - sm(3))
sm(1) = 0.5*(sm(1) + sm(3))
sm(2) = 0.5*(sm(2) + sm(4))
sm(3) = ts(1)
sm(4) = ts(2)
020 aq(1) = qz(1) - 1.57079632679490*(qn + 0.5)
aq(2) = qz(2)
ts(1) = cos(aq(1))*0.5*(exp(+aq(2)) + exp(-aq(2)))
ts(2) = -sin(aq(1))*0.5*(exp(+aq(2)) - exp(-aq(2)))
tm(1) = sm(1)*ts(1) - sm(2)*ts(2)
tm(2) = sm(1)*ts(2) + sm(2)*ts(1)
ts(1) = sin(aq(1))*0.5*(exp(+aq(2)) + exp(-aq(2)))
ts(2) = cos(aq(1))*0.5*(exp(+aq(2)) - exp(-aq(2)))
rm(1) = tm(1) - sm(3)*ts(1) + sm(4)*ts(2)
rm(2) = tm(2) - sm(3)*ts(2) - sm(4)*ts(1)
if (qn.eq.pn) go to 030
rm(3) = rm(1)
rm(4) = rm(2)
qn = qn + 1.0
if (zm.le.17.5) go to 025
021 an = qn*qn - 0.25
sm(1) = 0.0
sm(2) = 0.0
sm(3) = 0.0
sm(4) = 0.0
tm(1) = 1.0
tm(2) = 0.0
pm = 0.0
go to 023
022 an = an - 2.0*pm
pm = pm + 1.0
ts(1) = tm(1)*rz(1) - tm(2)*rz(2)
ts(2) = tm(1)*rz(2) + tm(2)*rz(1)
tm(1) = -an*ts(1)/pm
tm(2) = -an*ts(2)/pm
023 sm(1) = sm(1) + tm(1)
sm(2) = sm(2) + tm(2)
an = an - 2.0*pm
pm = pm + 1.0
ts(1) = tm(1)*rz(1) - tm(2)*rz(2)
ts(2) = tm(1)*rz(2) + tm(2)*rz(1)
tm(1) = an*ts(1)/pm
tm(2) = an*ts(2)/pm
if (abs(sm(3)) + abs(tm(1)).ne.abs(sm(3))) go to 024
if (abs(sm(4)) + abs(tm(2)).eq.abs(sm(4))) go to 027
024 sm(3) = sm(3) + tm(1)
sm(4) = sm(4) + tm(2)
if (pm.lt.35.0) go to 022
go to 027
025 sm(1) = 1.0
sm(2) = 0.0
sm(3) = 1.0
sm(4) = 0.0
m = 15.0*qn + 2.0
n = 15.0*qn + 15.0
do 026 i = m,n
   ts(1) = qz(2) - cd(i)
   ts(2) = -qz(1)
   ss = ts(1)*ts(1) + ts(2)*ts(2)
   tm(1) = ce(i)*ts(1)/ss
   tm(2) = -ce(i)*ts(2)/ss
   sm(1) = sm(1) + tm(1)
   sm(2) = sm(2) + tm(2)
   ts(1) = -qz(2) - cd(i)
   ts(2) = qz(1)
   ss = ts(1)*ts(1) + ts(2)*ts(2)
   tm(1) = ce(i)*ts(1)/ss
   tm(2) = -ce(i)*ts(2)/ss
   sm(3) = sm(3) + tm(1)
   sm(4) = sm(4) + tm(2)
026 continue
ts(1) = 0.5*(sm(2) - sm(4))
ts(2) = -0.5*(sm(1) - sm(3))
sm(1) = 0.5*(sm(1) + sm(3))
sm(2) = 0.5*(sm(2) + sm(4))
sm(3) = ts(1)
sm(4) = ts(2)
027 aq(1) = qz(1) - 1.57079632679490*(qn + 0.5)
aq(2) = qz(2)
ts(1) = cos(aq(1))*0.5*(exp(+aq(2)) + exp(-aq(2)))
ts(2) = -sin(aq(1))*0.5*(exp(+aq(2)) - exp(-aq(2)))
tm(1) = sm(1)*ts(1) - sm(2)*ts(2)
tm(2) = sm(1)*ts(2) + sm(2)*ts(1)
ts(1) = sin(aq(1))*0.5*(exp(+aq(2)) + exp(-aq(2)))
ts(2) = cos(aq(1))*0.5*(exp(+aq(2)) - exp(-aq(2)))
rm(1) = tm(1) - sm(3)*ts(1) + sm(4)*ts(2)
rm(2) = tm(2) - sm(3)*ts(2) - sm(4)*ts(1)
go to 029
028 tm(1) = 2.0*qn*qz(1)/zs
tm(2) = -2.0*qn*qz(2)/zs
ts(1) = tm(1)*rm(1) - tm(2)*rm(2) - rm(3)
ts(2) = tm(1)*rm(2) + tm(2)*rm(1) - rm(4)
rm(3) = rm(1)
rm(4) = rm(2)
rm(1) = ts(1)
rm(2) = ts(2)
qn = qn + 1.0
029 if (qn.lt.pn) go to 028
030 fj(1) = qf(1)*rm(1) - qf(2)*rm(2)
fj(2) = qf(1)*rm(2) + qf(2)*rm(1)
w = cmplx(fj(1),fj(2))
return
031 sz(1) = 0.25*(qz(1)*qz(1) - qz(2)*qz(2))
sz(2) = 0.5*qz(1)*qz(2)
an = qn
sm(1) = 0.0
sm(2) = 0.0
sm(3) = 0.0
sm(4) = 0.0
tm(1) = 1.0
tm(2) = 0.0
pm = 0.0
032 an = an + 1.0
ts(1) = tm(1)/an
ts(2) = tm(2)/an
sm(3) = sm(3) + ts(1)
sm(4) = sm(4) + ts(2)
tm(1) = -ts(1)*sz(1) + ts(2)*sz(2)
tm(2) = -ts(1)*sz(2) - ts(2)*sz(1)
pm = pm + 1.0
tm(1) = tm(1)/pm
tm(2) = tm(2)/pm
if (abs(sm(1)) + abs(tm(1)).ne.abs(sm(1))) go to 033
if (abs(sm(2)) + abs(tm(2)).eq.abs(sm(2))) go to 034
033 sm(1) = sm(1) + tm(1)
sm(2) = sm(2) + tm(2)
go to 032
034 sm(1) = sm(1) + 1.0
an = qn + 1.0
sm(3) = an*sm(3)
sm(4) = an*sm(4)
go to 036
035 an = qn*(qn + 1.0)
tm(1) = sz(1)/an
tm(2) = sz(2)/an
ts(1) = -tm(1)*sm(3) + tm(2)*sm(4)
ts(2) = -tm(1)*sm(4) - tm(2)*sm(3)
sm(3) = sm(1)
sm(4) = sm(2)
sm(1) = sm(1) + ts(1)
sm(2) = sm(2) + ts(2)
qn = qn - 1.0
036 if (qn.gt.pn) go to 035
qf(1) = sn
qf(2) = 0.0
qn = 0.0
go to 038
037 qn = qn + 1.0
tm(1) = qf(1)*qz(1) - qf(2)*qz(2)
tm(2) = qf(1)*qz(2) + qf(2)*qz(1)
qf(1) = 0.5*tm(1)/qn
qf(2) = 0.5*tm(2)/qn
038 if (qn.lt.pn) go to 037
fj(1) = qf(1)*sm(1) - qf(2)*sm(2)
fj(2) = qf(1)*sm(2) + qf(2)*sm(1)
w = cmplx(fj(1),fj(2))
return
end subroutine bsslj

subroutine besj(x, alpha, n, y, nz)
implicit none
!
!     Written by D.E. Amos, S.L. Daniel and M.K. Weston, January, 1975.
!
!     References
!         sand-75-0147
!
!         CDC 6600 subroutines ibess and JBESS for Bessel functions
!         i(NU,x) AND J(NU,x), x.GE.0, NU.GE.0  BY D.E. AMOS, S.L.
!         Daniel, M.K. Weston. ACM trans math software,3,PP 76-92
!         (1977)
!
!         Tables of Bessel functions of moderate or large orders,
!         npl mathematical tables, vol. 6, by F.W.J. Olver, her
!         majesty-S stationery office, london, 1962.
!
!     Abstract
!         besj computes an n member sequence of J Bessel functions
!         J/sub(alpha+k-1)/(x), k=1,...,n for non-negative alpha and x.
!         A combination of the power series, the asymptotic expansion
!         for x to infinity and the uniform asymptotic expansion for
!         nu to infinity are applied over subdivisions of the (NU,x)
!         plane. For values of (NU,x) not covered by one of these
!         formulae, the order is incremented or decremented by integer
!         values into a region where one of the formulae apply. Backward
!         recursion is applied to reduce orders by integer values except
!         where the entire sequence lies in the oscillatory region. In
!         this case forward recursion is stable and values from the
!         asymptotic expansion for x to infinity start the recursion
!         when it is efficient to do so. Leading terms of the series and
!         uniform expansion are tested for underflow. If a sequence is
!         requested and the last member would underflow, the result is
!         set to zero and the next lower order tried, etc., until A
!         member comes on scale or all members are set to zero. Overflow
!         cannot occur.
!
!         besj calls asjy, jairy, gamln, spmpar, and ipmpar
!
!     Description of arguments
!
!         Input
!           x      - x.GE.0.0E0
!           alpha  - Order of first member of the sequence,
!                    alpha.GE.0.0E0
!           n      - Number of members in the sequence, n.GE.1
!
!         Output
!           y      - A vector whose first n components contain
!                    values for J/sub(alpha+k-1)/(x), k=1,...,n
!           nz     - Error indicator
!                    nz=0      Normal return - Computation completed
!                    nz=-1     x is less than 0.0
!                    nz=-2     alpha is less than 0.0
!                    nz=-3     n is less than 1
!                    nz.GT.0   last nz components of y set to 0.0
!                              because of underflow
!
!     Error conditions
!         improper input arguments - A fatal error
!         UNDERFLOW  - A NON-FATAL ERROR (nz.GT.0)
!
integer, intent(in) :: n
integer, intent(inout) :: nz
real, intent(in) :: alpha
real :: x
real, intent(inout) :: y(n)
external jairy
integer :: i, ialp, idalp, iflw, in, inlim, is, i1, i2, k, kk, km, &
   & kt
integer :: nn, ns
integer :: ipmpar
real :: ak, akm
real :: ans, ap, arg, coef, dalpha, dfn, dtm, earg, elim, etx, &
   & fidal, flgjy, fn, fnf, fni, fnp1, fnu, fnulim(2), gln, pdf, pidt, &
   & pp(4), rden, relb, rttp, rtwo, rtx, rzden, s, sa, sb, sxo2, s1, &
   & s2, t, ta, tau, tb, temp(3), tfn, tm, tol, tolln, trx, tx, t1, t2, &
   & wk(7), xo2, xo2l
real :: gamln, spmpar
data rtwo,pdf,rttp,pidt                    / 1.34839972492648e+00, &
   & 7.85398163397448e-01, 7.97884560802865e-01, 1.57079632679490e+00/
data  pp(1),  pp(2),  pp(3),  pp(4)        / 8.72909153935547e+00, &
   & 2.65693932265030e-01, 1.24578576865586e-01, 7.70133747430388e-04/
data inlim           /      150            /
data fnulim(1), fnulim(2) /      100.0e0,     60.0e0     /
!     -------------------
!     ipmpar(8) replaces ipmpar(5) in a double precision code
!     ipmpar(9) replaces ipmpar(6) in a double precision code
!
!     Definition of the tolerances TOL and elim
!
tb = ipmpar(4)
ta = spmpar(1)/tb
if (tb.eq.2.0e0) go to 1
if (tb.eq.8.0e0) go to 2
if (tb.eq.16.0e0) go to 3
tb = alog(tb)
go to 5
1 tb = .69315e0
go to 5
2 tb = 2.07944e0
go to 5
3 tb = 2.77259e0
!
5 tol = amax1(ta,1.e-15)
i1 = ipmpar(5)
i2 = ipmpar(6)
!     ln(10**3) = 6.90776
elim = float(-i2)*tb - 6.90776e0
!     tolln = -ln(tol)
tolln = float(i1)*tb
tolln = amin1(tolln,34.5388e0)
!
!
!
nz = 0
kt = 1
if (n - 1) 720, 10, 20
10 kt = 2
20 nn = n
if (x) 730, 30, 80
30 if (alpha) 710, 40, 50
40 y(1) = 1.0e0
if (n.eq.1) return
i1 = 2
go to 60
50 i1 = 1
60 do i = i1,n
   y(i) = 0.0e0
end do
return
80 continue
if (alpha.lt.0.0e0) go to 710
!
ialp = int(alpha)
fni = float(ialp + n - 1)
fnf = alpha - float(ialp)
dfn = fni + fnf
fnu = dfn
xo2 = x*0.5e0
sxo2 = xo2*xo2
!
!     Decision tree for region where series, asymptotic expansion for x
!     to infinity and asymptotic expansion for nu to infinity are
!     applied.
!
if (sxo2.le.(fnu + 1.0e0)) go to 90
ta = amax1(20.0e0,fnu)
if (x.gt.ta) go to 120
if (x.gt.12.0e0) go to 110
xo2l = alog(xo2)
ns = int(sxo2 - fnu) + 1
go to 100
90 fn = fnu
fnp1 = fn + 1.0e0
xo2l = alog(xo2)
is = kt
if (x.le.0.50e0) go to 330
ns = 0
100 fni = fni + float(ns)
dfn = fni + fnf
fn = dfn
fnp1 = fn + 1.0e0
is = kt
if (n - 1 + ns.gt.0) is = 3
go to 330
110 ans = amax1(36.0e0 - fnu,0.0e0)
ns = int(ans)
fni = fni + float(ns)
dfn = fni + fnf
fn = dfn
is = kt
if (n - 1 + ns.gt.0) is = 3
go to 130
120 continue
rtx = sqrt(x)
tau = rtwo*rtx
ta = tau + fnulim(kt)
if (fnu.le.ta) go to 480
fn = fnu
is = kt
!
!     Uniform asymptotic expansion for nu to infinity
!
130 continue
i1 = iabs(3 - is)
i1 = max0(i1,1)
flgjy = 1.0e0
call asjy(jairy,x,fn,flgjy,i1,tol,elim,temp(is),wk,iflw)
if (iflw.ne.0) go to 380
go to (320, 450, 620), is
310 temp(1) = temp(3)
kt = 1
320 is = 2
fni = fni - 1.0e0
dfn = fni + fnf
fn = dfn
if (i1.eq.2) go to 450
go to 130
!
!     SERIES FOR (x/2)**2.LE.NU+1
!
330 continue
gln = gamln(fnp1)
arg = fn*xo2l - gln
if (arg.lt.(-elim)) go to 400
earg = exp(arg)
340 continue
s = 1.0e0
if (x.lt.tol) go to 360
ak = 3.0e0
t2 = 1.0e0
t = 1.0e0
s1 = fn
do k = 1,17
   s2 = t2 + s1
   t = -t*sxo2/s2
   s = s + t
   if (abs(t).lt.tol) go to 360
   t2 = t2 + ak
   ak = ak + 2.0e0
   s1 = s1 + fn
end do
360 continue
temp(is) = s*earg
go to (370, 450, 610), is
370 earg = earg*fn/xo2
fni = fni - 1.0e0
dfn = fni + fnf
fn = dfn
is = 2
go to 340
!
!     Set underflow value and update parameters
!
380 y(nn) = 0.0e0
nn = nn - 1
fni = fni - 1.0e0
dfn = fni + fnf
fn = dfn
if (nn - 1) 440, 390, 130
390 kt = 2
is = 2
go to 130
400 y(nn) = 0.0e0
nn = nn - 1
fnp1 = fn
fni = fni - 1.0e0
dfn = fni + fnf
fn = dfn
if (nn - 1) 440, 410, 420
410 kt = 2
is = 2
420 if (sxo2.le.fnp1) go to 430
go to 130
430 arg = arg - xo2l + alog(fnp1)
if (arg.lt.(-elim)) go to 400
go to 330
440 nz = n - nn
return
!
!     Backward recursion section
!
450 continue
nz = n - nn
if (kt.eq.2) go to 470
!     Backward recur from index alpha+nn-1 to alpha
y(nn) = temp(1)
y(nn - 1) = temp(2)
if (nn.eq.2) return
trx = 2.0e0/x
dtm = fni
tm = (dtm + fnf)*trx
k = nn + 1
do i = 3,nn
   k = k - 1
   y(k - 2) = tm*y(k - 1) - y(k)
   dtm = dtm - 1.0e0
   tm = (dtm + fnf)*trx
end do
return
470 y(1) = temp(2)
return
!
!     Asymptotic expansion for x to infinity with forward recursion in
!     oscillatory region x.GT.max(20, NU), provided the last member
!     of the sequence is also in the region.
!
480 continue
in = int(alpha - tau + 2.0e0)
if (in.le.0) go to 490
idalp = ialp - in - 1
kt = 1
go to 500
490 continue
idalp = ialp
in = 0
500 is = kt
fidal = float(idalp)
dalpha = fidal + fnf
arg = x - pidt*dalpha - pdf
sa = sin(arg)
sb = cos(arg)
coef = rttp/rtx
etx = 8.0e0*x
510 continue
dtm = fidal + fidal
dtm = dtm*dtm
tm = 0.0e0
if (fidal.eq.0.0e0 .and. abs(fnf).lt.tol) go to 520
tm = 4.0e0*fnf*(fidal + fidal + fnf)
520 continue
trx = dtm - 1.0e0
t2 = (trx + tm)/etx
s2 = t2
relb = tol*abs(t2)
t1 = etx
s1 = 1.0e0
fn = 1.0e0
ak = 8.0e0
do k = 1,13
   t1 = t1 + etx
   fn = fn + ak
   trx = dtm - fn
   ap = trx + tm
   t2 = -t2*ap/t1
   s1 = s1 + t2
   t1 = t1 + etx
   ak = ak + 8.0e0
   fn = fn + ak
   trx = dtm - fn
   ap = trx + tm
   t2 = t2*ap/t1
   s2 = s2 + t2
   if (abs(t2).le.relb) go to 540
   ak = ak + 8.0e0
end do
540 temp(is) = coef*(s1*sb - s2*sa)
if (is.eq.2) go to 560
550 fidal = fidal + 1.0e0
dalpha = fidal + fnf
is = 2
tb = sa
sa = -sb
sb = tb
go to 510
!
!     Forward recursion section
!
560 if (kt.eq.2) go to 470
s1 = temp(1)
s2 = temp(2)
tx = 2.0e0/x
tm = dalpha*tx
if (in.eq.0) go to 580
!
!     Forward recur to index alpha
!
do i = 1,in
   s = s2
   s2 = tm*s2 - s1
   tm = tm + tx
   s1 = s
end do
if (nn.eq.1) go to 600
s = s2
s2 = tm*s2 - s1
tm = tm + tx
s1 = s
580 continue
!
!     Forward recur from index alpha to alpha+n-1
!
y(1) = s1
y(2) = s2
if (nn.eq.2) return
do i = 3,nn
   y(i) = tm*y(i - 1) - y(i - 2)
   tm = tm + tx
end do
return
600 y(1) = s2
return
!
!     Backward recursion with normalization by
!     asymptotic expansion for nu to infinity or power series.
!
610 continue
!     Computation of last order for series normalization
akm = amax1(3.0e0 - fn,0.0e0)
km = int(akm)
tfn = fn + float(km)
ta = (gln + tfn - 0.9189385332e0 - 0.0833333333e0/tfn)/(tfn + 0.5e0)
ta = xo2l - ta
tb = -(1.0e0 - 1.5e0/tfn)/tfn
akm = tolln/(-ta + sqrt(ta*ta - tolln*tb)) + 1.5e0
in = km + int(akm)
go to 660
620 continue
!     Computation of last order for asymptotic expansion normalization
gln = wk(3) + wk(2)
if (wk(6).gt.30.0e0) go to 640
rden = (pp(4)*wk(6) + pp(3))*wk(6) + 1.0e0
rzden = pp(1) + pp(2)*wk(6)
ta = rzden/rden
if (wk(1).lt.0.10e0) go to 630
tb = gln/wk(5)
go to 650
630 tb = (1.259921049e0 + (0.1679894730e0 + 0.0887944358e0*wk(1))*wk(1)) &
   & /wk(7)
go to 650
640 continue
ta = 0.5e0*tolln/wk(4)
ta = ((0.0493827160e0*ta - 0.1111111111e0)*ta + 0.6666666667e0)*ta*wk(6)
if (wk(1).lt.0.10e0) go to 630
tb = gln/wk(5)
650 in = int(ta/tb + 1.5e0)
if (in.gt.inlim) go to 310
660 continue
dtm = fni + float(in)
trx = 2.0e0/x
tm = (dtm + fnf)*trx
ta = 0.0e0
tb = tol
kk = 1
670 continue
!
!     Backward recur unindexed
!
do i = 1,in
   s = tb
   tb = tm*tb - ta
   ta = s
   dtm = dtm - 1.0e0
   tm = (dtm + fnf)*trx
end do
!     Normalization
if (kk.ne.1) go to 690
ta = (ta/tb)*temp(3)
tb = temp(3)
kk = 2
in = ns
if (ns.ne.0) go to 670
690 y(nn) = tb
nz = n - nn
if (nn.eq.1) return
k = nn - 1
y(k) = tm*tb - ta
if (nn.eq.2) return
dtm = dtm - 1.0e0
tm = (dtm + fnf)*trx
km = k - 1
!
!     Backward recur indexed
!
do i = 1,km
   y(k - 1) = tm*y(k) - y(k + 1)
   dtm = dtm - 1.0e0
   tm = (dtm + fnf)*trx
   k = k - 1
end do
return
!
!
!
710 continue
nz = -2
return
720 continue
nz = -3
return
730 continue
nz = -1
return
end subroutine besj

subroutine asjy(funjy,x,fnu,flgjy,in,tol,elim,y,wk,iflw)
implicit none
!
!               asjy computes Bessel functions j and y
!               for arguments x.GT.0.0 and orders fnu.GE.35.0
!               ON flgjy = 1 AND flgjy = -1 RESPECTIVELY
!
!                                  Input
!
!      FUNJY - External function jairy or YAIRY
!          x - ARGUMENT, x.GT.0.0E0
!        fnu - Order of the first Bessel function
!      flgjy - Selection flag
!              flgjy =  1.0E0 gives the j function
!              flgjy = -1.0E0 gives the y function
!         in - Number of functions desired, in = 1 Or 2
!        tol - Tolerance specified by besj or BESY
!       elim - Tolerance specified by besj or BESY
!
!                                  Output
!
!         y  - A vector whose first in components contain the sequence
!       iflw - A flag indicating underflow or overflow
!                    RETURN VARIABLES FOR besj ONLY
!      wk(1) = 1 - (x/fnu)**2 = w**2
!      wk(2) = sqrt(abs(wk(1)))
!      wk(3) = abs(wk(2) - atan(wk(2)))  or
!              abs(LN((1 + wk(2))/(x/fnu)) - wk(2))
!            = abs((2/3)*ZETA**(3/2))
!      wk(4) = fnu*wk(3)
!      wk(5) = (1.5*wk(3)*fnu)**(1/3) = sqrt(zeta)*fnu**(1/3)
!      wk(6) = sign(1.,w**2)*wk(5)**2 = sign(1.,w**2)*zeta*fnu**(2/3)
!      wk(7) = fnu**(1/3)
!
!                                  Written by
!                                  D. E. Amos
!
!     Abstract
!         ASJK implements the uniform asymptotic expansion of
!         the j and y Bessel functions for fnu.GE.35 and real
!         x.GT.0.0E0. The forms are identical except for a change
!         in sign of some of the terms. This change in sign is
!         accomplished by means of the flag flgjy = 1 Or -1. On
!         flgjy = 1 The Airy functions ai(x) and dai(x) are
!         supplied by the external function jairy, and on
!         flgjy = -1 The Airy functions bi(x) and DBI(x) are
!         supplied by the external funtion YAIRY.
!
integer :: iflw, in
real :: elim, flgjy, fnu, tol, wk(*), x, y(*)
external funjy
integer :: i, j, jn, jr, ju, k, kb, klast, kmax(5), kp1, ks, ksp1, &
   & kstemp, l, lr, lrp1
real :: abw2, akm, alfa(26,4), alfa1(26,2), alfa2(26,2), ap, &
   & ar(8), asum, az, beta(26,5), beta1(26,2), beta2(26,2), &
   & beta3(26,1), br(10), bsum, c(65), con1, con2, con3, con548, &
   & cr(10), crz32, dfi, dr(10), fi, fn, fn2, gama(26), phi, rcz, rden, &
   & relb, rfn2, rtz, rzden, sa, sb, suma, sumb, s1, ta, tau, tb, tfn, &
   & tols, t2, upol(10), xx, z, z32
equivalence (alfa(1,1),alfa1(1,1))
equivalence (alfa(1,3),alfa2(1,1))
equivalence (beta(1,1),beta1(1,1))
equivalence (beta(1,3),beta2(1,1))
equivalence (beta(1,5),beta3(1,1))
data tols            /-6.90775527898214e+00/
data con1,con2,con3,con548/ &
   & 6.66666666666667e-01, 3.33333333333333e-01, 1.41421356237310e+00, &
   & 1.04166666666667e-01/
data  ar(1),  ar(2),  ar(3),  ar(4),  ar(5),  ar(6),  ar(7), &
   & ar(8)          / 8.35503472222222e-02, 1.28226574556327e-01, &
   & 2.91849026464140e-01, 8.81627267443758e-01, 3.32140828186277e+00, &
   & 1.49957629868626e+01, 7.89230130115865e+01, 4.74451538868264e+02/
