if (x.lt.0.) go to 300
if (c.gt.5.) go to 200
if (x.gt.1.2) go to 150
t = (x + x - 1.2)*con4
tt = t + t
j = n1
f1 = ak1(j)
f2 = 0.
do i = 1,m1
   j = j - 1
   temp1 = f1
   f1 = tt*f1 - f2 + ak1(j)
   f2 = temp1
end do
ai = t*f1 - f2 + ak1(1)
!
j = n1d
f1 = dak1(j)
f2 = 0.
do i = 1,m1d
   j = j - 1
   temp1 = f1
   f1 = tt*f1 - f2 + dak1(j)
   f2 = temp1
end do
dai = -(t*f1 - f2 + dak1(1))
return
!
150 continue
t = (x + x - con2)*con3
