   j = j - 1
   temp1 = f1
   f1 = tt*f1 - f2 + ak2(j)
   f2 = temp1
end do
rtrx = sqrt(rx)
ec = exp(-c)
ai = ec*(t*f1 - f2 + ak2(1))/rtrx
j = n2d
f1 = dak2(j)
f2 = 0.
do i = 1,m2d
   j = j - 1
   temp1 = f1
   f1 = tt*f1 - f2 + dak2(j)
   f2 = temp1
end do
dai = -ec*(t*f1 - f2 + dak2(1))*rtrx
return
!
200 continue
t = 10./c - 1.
tt = t + t
j = n1
f1 = ak3(j)
f2 = 0.
do i = 1,m1
   j = j - 1
   temp1 = f1
   f1 = tt*f1 - f2 + ak3(j)
   f2 = temp1
end do
rtrx = sqrt(rx)
ec = exp(-c)
ai = ec*(t*f1 - f2 + ak3(1))/rtrx
j = n1d
f1 = dak3(j)
f2 = 0.
do i = 1,m1d
   j = j - 1
   temp1 = f1
   f1 = tt*f1 - f2 + dak3(j)
   f2 = temp1
end do
dai = -rtrx*ec*(t*f1 - f2 + dak3(1))
return
!
300 continue
if (c.gt.5.) go to 350
t = .4*c - 1.
tt = t + t
j = n3
f1 = ajp(j)
e1 = ajn(j)
f2 = 0.
e2 = 0.
do i = 1,m3
   j = j - 1
   temp1 = f1
   temp2 = e1
   f1 = tt*f1 - f2 + ajp(j)
   e1 = tt*e1 - e2 + ajn(j)
   f2 = temp1
   e2 = temp2
end do
ai = (t*e1 - e2 + ajn(1)) - x*(t*f1 - f2 + ajp(1))
j = n3d
f1 = dajp(j)
e1 = dajn(j)
f2 = 0.
e2 = 0.
do i = 1,m3d
   j = j - 1
   temp1 = f1
   temp2 = e1
   f1 = tt*f1 - f2 + dajp(j)
   e1 = tt*e1 - e2 + dajn(j)
   f2 = temp1
   e2 = temp2
end do
dai = x*x*(t*f1 - f2 + dajp(1)) + (t*e1 - e2 + dajn(1))
return
!
350 continue
t = 10./c - 1.
tt = t + t
j = n4
f1 = a(j)
e1 = b(j)
f2 = 0.
e2 = 0.
do i = 1,m4
   j = j - 1
   temp1 = f1
   temp2 = e1
   f1 = tt*f1 - f2 + a(j)
   e1 = tt*e1 - e2 + b(j)
   f2 = temp1
   e2 = temp2
end do
temp1 = t*f1 - f2 + a(1)
temp2 = t*e1 - e2 + b(1)
rtrx = sqrt(rx)
cv = c - fpi12
ccv = cos(cv)
scv = sin(cv)
ai = (temp1*ccv - temp2*scv)/rtrx
j = n4d
f1 = da(j)
e1 = db(j)
f2 = 0.
e2 = 0.
do i = 1,m4d
   j = j - 1
   temp1 = f1
   temp2 = e1
   f1 = tt*f1 - f2 + da(j)
   e1 = tt*e1 - e2 + db(j)
   f2 = temp1
   e2 = temp2
end do
temp1 = t*f1 - f2 + da(1)
temp2 = t*e1 - e2 + db(1)
e1 = ccv*con5 + .5*scv
e2 = scv*con5 - .5*ccv
dai = (temp1*e1 - temp2*e2)*rtrx
return
end subroutine jairy

subroutine bssly (a, in, w)
implicit none
