   & ce(28)/ 9.84215550625747e-5/,  ce(29)/ 7.32139093038089e-6/, &
   & ce(30)/ 1.37279667384666e-7/
!     -------------------
az(1) = real(a)
az(2) = aimag(a)
zs = az(1)*az(1) + az(2)*az(2)
zl(1) = 0.5*alog(zs)
zl(2) = atan2(az(2),az(1))
an = iabs(in)
sn = 1.0
if (in) 002,003,003
002 if (in.eq.in/2*2) go to 003
sn = -1.0
003 if (az(1)) 004,005,005
