qz(2) = az(2)
006 if (zs - 1.0) 020,020,007
007 if (zs - 289.0) 008,010,010
008 if (-abs(az(2)) + 0.096*az(1)*az(1)) 020,020,015
010 qm = sn*0.797884560802865*exp(-0.5*zl(1))
qf(1) = qm*cos(-0.5*zl(2))
qf(2) = qm*sin(-0.5*zl(2))
if (an.gt.1.0) go to 012
